"""L3 droit : cas pratiques et qualifications en droit du travail (principes généraux).

Mises en situation fictives : qualification du contrat, pouvoirs de l'employeur, rupture, représentation, grève, conflits, sécurité.
"""
from .sup_kit import *  # noqa: F401,F403

source("sup-cas-l3a", "Droit du travail : cas pratiques et qualifications", "cours de L3 droit",
       "Comparer avec un manuel de droit du travail (Code du travail applicable, conventions de l'OIT) ; les solutions précises varient selon les pays, d'où les mentions « en droit français » ou « de façon générale ».")

C = "Droit du travail (cas pratiques)"
CRS = "l3-droit"


def M(base, rows, cat=C, size=18):
    """Découpe les questions en lots (un modèle par lot) pour que chaque tpl reste petit."""
    for i in range(0, len(rows), size):
        mcq(CRS, "cas-l3a-%s%d" % (base, i // size + 1), rows[i:i + size], cat=cat, src="sup-cas-l3a")


# ---------------------------------------------------------------- 1. Qualification du contrat de travail
M("qual", [
    ("Mme Ngono répare le matériel d'une société, aux horaires imposés, avec les outils fournis et sous le contrôle d'un chef d'atelier. Comment qualifier la relation ?", "Un contrat de travail, car elle est subordonnée à la société", ["Un contrat d'entreprise, car elle réalise une tâche précise pour un client", "Un mandat, car elle agit pour le compte de la société", "Un contrat de société, car elle apporte son travail", "Un bénévolat, car elle ne choisit pas ses outils"], "Horaires imposés, direction et contrôle caractérisent le lien de subordination.", 2),
    ("Un artisan s'engage à livrer un meuble sur commande, choisit ses horaires et ses méthodes, et facture son client. Quelle qualification est la plus plausible ?", "Un contrat d'entreprise", ["Un contrat de travail à durée indéterminée classique", "Un contrat d'apprentissage", "Un contrat de travail à durée déterminée", "Un contrat de société en participation"], "Sans ordres ni contrôle de l'exécution, il n'y a pas de lien de subordination.", 2),
    ("Les parties ont intitulé leur accord « contrat de prestation de services », mais la personne reçoit des ordres quotidiens et peut être sanctionnée. Que décidera le juge ?", "Il requalifiera en contrat de travail d'après la réalité des faits", ["Il respectera le titre choisi par les parties", "Il déclarera le contrat inexistant", "Il le qualifiera de contrat de société", "Il laissera l'employeur choisir librement la qualification retenue"], "Les faits priment sur la dénomination donnée par les parties.", 3),
    ("Quel élément est, de façon générale, décisif pour qualifier un contrat de travail ?", "Le lien de subordination juridique", ["Le versement d'une somme d'argent, quelle qu'elle soit", "L'existence d'un écrit signé", "L'appartenance du travailleur à un syndicat", "La durée de la relation de travail"], "Travail, rémunération et subordination sont requis ; la subordination est l'élément distinctif.", 2),
    ("M. Tchoumi aide ponctuellement son voisin à construire sa clôture, sans rien recevoir ni être dirigé. Existe-t-il un contrat de travail ?", "Non, il manque la rémunération et la subordination", ["Oui, car un travail a été accompli", "Oui, car l'aide a été utile au voisin", "Oui, mais seulement à durée déterminée", "Oui, car la clôture ainsi construite appartient désormais au voisin"], "Un service gratuit rendu sans direction n'est pas un contrat de travail.", 2),
    ("Une association fait distribuer des tracts par des personnes qui ne reçoivent aucune rémunération et participent librement. De quoi s'agit-il en principe ?", "De bénévolat, sans rémunération", ["D'un contrat de travail à durée indéterminée", "D'un contrat d'apprentissage", "D'un contrat de travail temporaire", "D'un contrat de société civile entre les deux parties"], "La gratuité et la liberté d'engagement caractérisent le bénévolat.", 2),
    ("Un travailleur est dit « indépendant » sur le papier, mais il dépend d'un seul donneur d'ordre qui fixe ses tournées et le sanctionne. Que révèle ce faisceau d'indices ?", "Un possible contrat de travail déguisé", ["Un contrat de bail commercial", "Un contrat de vente de marchandises", "Une société de fait entre les deux parties", "Un contrat de dépôt"], "Le juge recherche, par un faisceau d'indices, l'existence d'une subordination réelle.", 4),
    ("Dans la méthode du « faisceau d'indices », que cherche à établir le juge ?", "Les conditions réelles d'exécution du travail, pour savoir s'il y a subordination", ["La seule volonté exprimée dans le contrat", "La nationalité des parties", "Le montant des impôts payés par le travailleur", "L'ancienneté de l'entreprise sur le marché"], "Le juge examine les circonstances concrètes de l'exécution, pas l'étiquette.", 3),
    ("Un étudiant effectue un stage prévu par sa formation, encadré par une convention avec son établissement, avec un objectif pédagogique. Quelle est la logique de ce stage ?", "Une finalité de formation, distincte d'un emploi ordinaire", ["Un emploi salarié normal sans particularité", "Un mandat donné à l'étudiant", "Une société en participation entre l'étudiant et l'entreprise d'accueil", "Un prêt de main-d'œuvre entre entreprises"], "Le stage vise l'apprentissage ; s'il masque un vrai poste, il peut être requalifié.", 3),
    ("Un « stagiaire » occupe durablement un poste de travail, remplace un salarié absent et reçoit des ordres comme les autres. Quel risque cela fait-il courir à l'entreprise ?", "La requalification du stage en contrat de travail", ["La transformation automatique du stage en contrat de société commerciale", "L'obligation de dissoudre l'entreprise", "La nullité de tous les contrats de l'entreprise", "La perte automatique de la personnalité morale"], "Un stage détourné de sa finalité pédagogique peut être requalifié en contrat de travail.", 4),
    ("Un employeur engage un travailleur sans écrit, mais lui donne chaque jour des consignes et lui verse un salaire. Le contrat de travail existe-t-il ?", "Oui, en principe l'accord peut résulter des faits même sans écrit", ["Non, un contrat de travail exige toujours un écrit signé devant notaire", "Non, seul un contrat écrit protège le travailleur", "Oui, mais seulement après un an de relation", "Non, tant que le syndicat n'a pas été consulté"], "Le contrat de travail se prouve par tous moyens ; l'écrit n'est pas, en principe, une condition d'existence.", 3),
    ("Dans un contrat de travail, que doit à l'employeur le salarié, de façon générale ?", "Sa prestation de travail exécutée sous la direction de l'employeur", ["Une part des bénéfices de l'entreprise", "La propriété de ses outils personnels", "Une garantie bancaire sur son salaire", "L'obligation de financer l'entreprise"], "Le salarié fournit un travail ; l'employeur paie le salaire.", 1),
    ("Un livreur utilise son propre véhicule, fixe librement ses horaires, peut refuser des courses et travaille aussi pour d'autres clients. Quel indice milite contre le contrat de travail ?", "Son autonomie dans l'organisation et la pluralité de clients", ["Le fait qu'il reçoive une somme d'argent", "Le fait qu'il livre des marchandises", "Le fait qu'il connaisse l'adresse de l'entreprise pour laquelle il livre", "Le fait qu'il utilise un véhicule"], "L'autonomie et l'absence d'exclusivité révèlent plutôt une activité indépendante.", 3),
    ("Un avocat plaide pour un client qui lui verse des honoraires, sans recevoir d'ordres sur la manière de plaider. Cette relation est plutôt de quel ordre ?", "D'un mandat ou d'une prestation libérale, sans subordination", ["D'un contrat de travail à durée indéterminée classique entre eux", "D'un contrat d'apprentissage", "D'un contrat de travail temporaire", "D'une société entre l'avocat et son client"], "L'indépendance dans la conduite de la mission exclut la subordination.", 3),
    ("Un salarié est détaché dans une autre entreprise pendant quelques mois, mais son employeur d'origine continue de le payer et reste son employeur. Que reste-t-il, en principe ?", "Le contrat avec l'employeur d'origine", ["Un nouveau contrat avec l'entreprise d'accueil, automatiquement", "L'absence de tout contrat pendant le détachement", "Un contrat de société avec l'entreprise d'accueil", "Un contrat d'apprentissage"], "Le détachement ne rompt pas le contrat ; l'employeur d'origine demeure l'employeur.", 4),
    ("Un travailleur est mis à disposition d'une entreprise utilisatrice par une agence de travail temporaire. Qui est, en principe, son employeur juridique ?", "L'agence de travail temporaire", ["L'entreprise utilisatrice", "L'État", "Le syndicat des intérimaires", "Le client de l'entreprise utilisatrice"], "L'intérimaire est lié par contrat de travail à l'agence, qui le met à disposition.", 3),
    ("Le contrat de travail à durée indéterminée est, en principe, quelle forme de relation ?", "La forme normale de la relation de travail", ["Une forme réservée aux cadres supérieurs seulement", "Une forme interdite sauf autorisation du juge", "Une forme réservée aux entreprises publiques", "Une forme limitée aux travailleurs saisonniers"], "Le CDD est une exception encadrée à cette forme normale.", 2),
    ("Une entreprise conclut des CDD successifs pour pourvoir un poste durable et permanent, sans motif légitime. Quelle sanction est classique en droit français ?", "La requalification en contrat à durée indéterminée", ["La nullité de l'entreprise", "La transformation du poste en mandat", "La rupture automatique sans indemnité", "La conversion automatique en contrat d'apprentissage de l'intéressé"], "Le recours au CDD ne peut avoir pour objet de pourvoir durablement un emploi permanent.", 4),
    ("En droit français, un contrat à durée déterminée peut être conclu en principe pour quoi ?", "Une tâche précisée et temporaire, dans les cas prévus", ["N'importe quel emploi, durable ou non, sans aucune condition de motif", "Un emploi durable lié à l'activité normale", "Uniquement les emplois de direction", "Uniquement les travaux de nuit"], "Le CDD est ouvert dans des cas limités liés au caractère temporaire de la tâche.", 3),
    ("Que permet, en principe, la période d'essai ?", "Évaluer les capacités du salarié et vérifier que l'emploi convient aux deux parties", ["Priver le salarié de toute rémunération", "Supprimer pour toujours l'obligation de sécurité", "Dispenser l'employeur de toute règle de discrimination", "Remplacer le contrat de travail"], "L'essai sert à tester la collaboration ; les droits fondamentaux du salarié subsistent.", 2),
    ("Pendant la période d'essai, un employeur met fin au contrat pour un motif discriminatoire. Que peut-on dire ?", "La liberté de rompre n'autorise pas une rupture discriminatoire", ["La rupture est toujours valable pendant l'essai", "La rupture devient valable après le préavis", "La discrimination est permise tant que l'essai n'est pas rémunéré", "Seul le salarié peut agir devant le juge"], "Même libre, la rupture ne peut reposer sur un motif illicite.", 4),
    ("Que reste, en principe, un salarié à temps partiel ?", "Un salarié comme les autres, avec un horaire inférieur à l'horaire de l'entreprise", ["Un travailleur indépendant", "Un bénévole", "Un stagiaire en formation", "Un associé de l'entreprise"], "Le temps partiel est une modalité du contrat de travail, pas une absence de contrat.", 2),
    ("Une société qui change de forme juridique continue d'employer ses salariés. Que devient, de façon générale, le contrat de travail ?", "Il se poursuit avec le nouvel employeur", ["Il est automatiquement rompu", "Il devient un contrat d'entreprise", "Il est suspendu jusqu'à décision du juge", "Il devient un contrat à durée déterminée"], "En cas de modification dans la situation juridique de l'employeur, les contrats en cours subsistent.", 4),
    ("Dans un contrat de travail, de quoi la rémunération est-elle la contrepartie ?", "Du travail fourni au profit de l'employeur", ["De la fidélité du salarié à son syndicat ou à son équipe", "Du capital apporté par le salarié", "De l'ancienneté de l'entreprise", "De la nationalité du salarié"], "Le salaire est la contrepartie du travail accompli.", 1),
    ("Un travailleur à domicile reçoit des matières de l'entreprise, fabrique des pièces selon ses consignes précises et les rend en échange d'une paie. Quelle conclusion est plausible ?", "La subordination peut exister même sans présence dans les locaux", ["Il n'y a jamais de contrat de travail pour un travail hors des locaux", "Il est associé de l'entreprise", "Il est un bénévole", "Il est un client de l'entreprise"], "La subordination se mesure à la direction du travail, pas au lieu d'exécution.", 4),
    ("Un salarié exécute ses tâches en télétravail, mais l'employeur fixe les objectifs, contrôle les résultats et peut sanctionner. Quel est l'effet sur la qualification ?", "Le contrat de travail demeure, la subordination subsistant à distance", ["Il devient un contrat d'entreprise", "Il devient un mandat", "Il perd sa nature de contrat de travail", "Il se transforme en société"], "Le lieu d'exécution n'efface pas le pouvoir de direction.", 3),
    ("Un employé qui exerce une grande autonomie technique (par exemple un ingénieur) peut-il être salarié ?", "Oui, l'autonomie technique n'exclut pas la subordination juridique", ["Non, un salarié doit toujours exécuter des gestes précis imposés d'en haut", "Non, seuls les ouvriers peuvent être salariés", "Oui, mais seulement à temps partiel", "Non, il serait nécessairement associé"], "La subordination est juridique, non technique : l'employeur garde le pouvoir de direction.", 4),
    ("Qu'est-ce qui distingue le salarié du mandataire qui agit pour le compte d'un mandant ?", "Le salarié est subordonné, le mandataire accomplit des actes juridiques pour autrui", ["Le salarié choisit seul ses missions, le mandataire non", "Le salarié est toujours bénévole", "Le mandataire est toujours payé en nature", "Il n'y a aucune différence"], "Le mandat porte sur des actes juridiques accomplis pour le mandant, sans subordination nécessaire.", 5),
    ("Un travailleur est engagé pour une durée fixée à l'avance, à l'expiration de laquelle le contrat s'achève sauf renouvellement. Quel type de contrat est-ce ?", "Un contrat à durée déterminée", ["Un contrat à durée indéterminée", "Un contrat d'entreprise", "Un contrat de société", "Un contrat de bail"], "Le terme fixé à l'avance est le critère du contrat à durée déterminée.", 1),
    ("Dans l'apprentissage, quel élément caractérise le contrat, de façon générale ?", "L'alternance entre la formation et le travail en entreprise", ["L'absence de toute formation", "L'absence de toute rémunération", "La direction du travail par l'apprenti", "L'exclusion du droit du travail"], "L'apprenti est formé en travaillant, sous l'autorité d'un maître d'apprentissage.", 2),
    ("Le gérant d'une boutique gère librement l'établissement et se rémunère sur les résultats, sans recevoir d'instructions, en payant une redevance au propriétaire. Quel indice joue contre le contrat de travail ?", "L'absence de direction et le risque économique supporté", ["Le fait que la boutique soit ouverte au public et vende des produits", "Le fait que le gérant soit rémunéré", "Le fait que la boutique ait un propriétaire", "Le fait que le gérant travaille régulièrement"], "L'indépendance de gestion et le risque économique sont des indices d'indépendance.", 5),
    ("En cas de doute sur la nature de la relation, qui tranche si les parties ne s'accordent pas ?", "Le juge compétent, selon les faits établis", ["Le seul employeur, qui impose sa qualification", "Le seul travailleur, qui choisit sa qualification", "Le syndicat de l'entreprise", "Le tirage au sort"], "La qualification juridique est une question relevant du juge.", 2),
    ("Une personne exerce un travail pour une entreprise, dissimulé et non déclaré, pour ne pas payer de cotisations. Comment appelle-t-on cette situation, de façon générale ?", "Le travail dissimulé", ["Le travail à temps partiel", "Le travail saisonnier", "Le détachement", "L'apprentissage"], "Le travail dissimulé consiste à éluder les obligations déclaratives liées à l'emploi.", 3),
    ("Un salarié exerce son activité dans une entreprise sans que son employeur l'ait déclaré. Que signifie cela pour l'existence de son contrat ?", "Le contrat existe malgré l'absence de déclaration, qui constitue un manquement", ["Le contrat n'existe pas", "Le contrat est nul pour l'avenir seulement", "Le contrat devient un contrat d'entreprise", "Le salarié devient associé"], "Le défaut de déclaration n'efface pas l'existence du contrat de travail.", 4),
    ("Quelle est la conséquence pour l'employeur qui a fait travailler une personne en dehors de toute déclaration ?", "Il s'expose à des sanctions pour travail dissimulé", ["Il devient le débiteur de ses concurrents", "Il peut réduire librement le salaire", "Il est dispensé de toute obligation envers le salarié", "Il peut rompre le contrat sans motif"], "Le travail dissimulé est sanctionné, notamment par des peines et des indemnités.", 3),
    ("Le critère du « pouvoir de sanction » est un indice de quoi ?", "De l'existence d'une subordination juridique", ["De l'existence d'un contrat de vente entre les parties", "De l'absence de contrat", "De la qualité d'associé", "De la nature civile de l'entreprise"], "Le pouvoir de sanctionner les manquements est l'un des attributs de l'employeur.", 3),
    ("Parmi ces éléments, lequel est un indice de subordination ?", "L'obligation de suivre des horaires fixés par le donneur d'ordre", ["Le fait d'être payé en fin de mois", "Le fait d'avoir un compte bancaire", "Le fait de travailler en équipe avec des collègues dans une même salle", "Le fait de travailler dans une ville"], "L'imposition des horaires est un indice classique de direction.", 2),
    ("Parmi ces éléments, lequel est plutôt un indice d'indépendance ?", "Le fait de fixer librement ses tarifs et de prospecter sa clientèle", ["Le fait de suivre un règlement intérieur", "Le fait d'être sanctionné par un supérieur", "Le fait de recevoir des instructions détaillées", "Le fait d'utiliser du matériel fourni par le donneur d'ordre lui-même"], "La liberté de clientèle et de tarif est caractéristique de l'indépendance.", 3),
    ("Un cadre dirigeant d'une entreprise peut-il être lié par un contrat de travail ?", "Oui, s'il demeure subordonné à l'organe qui dirige la société", ["Non, un dirigeant n'est jamais salarié", "Oui, mais seulement si le contrat de travail n'est pas conclu par écrit", "Non, car il possède l'entreprise", "Oui, mais jamais avec rémunération"], "Un dirigeant peut cumuler contrat de travail et fonction si une réelle subordination existe.", 5),
    ("Le contrat de travail est-il un contrat à titre onéreux ?", "Oui, chaque partie reçoit un avantage en contrepartie de ce qu'elle donne", ["Non, c'est toujours un contrat gratuit", "Non, il est unilatéral", "Oui, mais seul l'employeur en retire un avantage", "Non, il est réel"], "Travail et salaire sont échangés : le contrat est synallagmatique et onéreux.", 3),
    ("Parmi ces contrats, lequel n'est pas un contrat de travail ?", "Le contrat d'entreprise", ["Le contrat à durée indéterminée", "Le contrat à durée déterminée", "Le contrat d'apprentissage", "Le contrat de travail à temps partiel"], "Le contrat d'entreprise est un contrat de prestation indépendante.", 2),
    ("Un employeur conteste l'existence d'un contrat de travail en soutenant que la personne était indépendante. Sur qui pèse, en principe, la charge de prouver le contrat de travail ?", "Sur celui qui s'en prévaut, c'est-à-dire en général le travailleur", ["Sur l'employeur dans tous les cas", "Sur l'inspecteur du travail", "Sur le syndicat", "Sur aucune des parties"], "Celui qui invoque l'existence d'un contrat de travail doit en prouver les éléments.", 4),
    ("Le prêt de main-d'œuvre à but lucratif entre entreprises est, de façon générale, traité comment ?", "Encadré, voire interdit hors des cadres prévus par la loi", ["Toujours libre sans condition", "Obligatoire pour tout employeur", "Réservé aux associations", "Ouvert seulement aux étrangers"], "Le marchandage et le prêt illicite de main-d'œuvre sont combattus pour protéger les salariés.", 5),
    ("Un salarié accepte un poste ; l'employeur lui présente ensuite un contrat contenant une clause le privant de tout droit de contester son licenciement. Que penser de cette clause ?", "Elle est sans effet, car on ne peut renoncer par avance à ses droits d'ordre public", ["Elle est valable car le salarié a signé", "Elle est valable si l'employeur est de bonne foi", "Elle est valable si le poste est qualifié", "Elle est valable seulement pour les cadres"], "Les règles protectrices d'ordre public ne souffrent pas de renonciation anticipée.", 4),
    ("Un contrat de travail est conclu avec un mineur, avec l'accord de son représentant légal, pour un travail dangereux. Quel principe général s'applique ?", "Le travail des jeunes est encadré et certains travaux leur sont interdits", ["Le mineur est libre de tout travail", "L'accord du représentant légal valide tout travail", "Seule la rémunération importe", "Le mineur est traité comme un adulte sur tout"], "Les mineurs bénéficient de règles protectrices spécifiques.", 3),
    ("L'employeur a le droit de choisir son salarié. Quelle limite générale s'impose à ce choix ?", "L'interdiction de toute discrimination illégitime", ["L'obligation de choisir le plus âgé", "L'obligation de recruter un parent proche d'un salarié de l'entreprise", "L'obligation d'obtenir l'accord des syndicats", "L'obligation de recruter par tirage au sort"], "Le recrutement doit reposer sur des critères professionnels, non discriminatoires.", 3),
], size=15)
# ---------------------------------------------------------------- 2. Pouvoirs de l'employeur
M("pouv", [
    ("Un employeur impose un nouveau logiciel de facturation à tous ses employés. Quel pouvoir exerce-t-il ?", "Son pouvoir de direction", ["Son pouvoir de représenter légalement les salariés", "Son pouvoir de juger les litiges entre salariés", "Son pouvoir de fixer les lois du travail", "Son pouvoir de négocier une convention collective de branche"], "Le pouvoir de direction permet d'organiser le travail et de donner des instructions.", 2),
    ("Une entreprise adopte un règlement intérieur fixant les horaires d'accès, les règles d'hygiène et les sanctions. Quel pouvoir est en jeu ?", "Le pouvoir réglementaire de l'employeur", ["Le pouvoir législatif de l'État dans l'entreprise", "Le pouvoir de contrôle exercé par l'inspecteur du travail", "Le pouvoir de juger donné au conseil d'administration", "Le pouvoir de négociation reconnu aux syndicats"], "L'employeur édicte des règles générales applicables dans l'entreprise.", 2),
    ("Un employeur inflige un avertissement à un salarié arrivé en retard de façon répétée. Quel pouvoir exerce-t-il ?", "Son pouvoir disciplinaire", ["Son pouvoir de direction sur les congés payés", "Son pouvoir de représentation de l'entreprise", "Son pouvoir de contrôle des comptes du syndicat", "Son pouvoir d'arbitrage entre salariés"], "Sanctionner une faute relève du pouvoir disciplinaire.", 2),
    ("Un employeur sanctionne un salarié deux fois pour le même retard : un avertissement, puis une mise à pied. Quelle règle est méconnue ?", "Une même faute ne peut être sanctionnée deux fois", ["Le salarié doit toujours être sanctionné trois fois", "L'employeur ne peut jamais prononcer d'avertissement", "La mise à pied est réservée au syndicat", "Le retard ne peut jamais être une faute"], "Le principe non bis in idem s'applique au pouvoir disciplinaire.", 3),
    ("Avant de prononcer une sanction disciplinaire, l'employeur ne fait pas entendre le salarié. Quel principe général est violé ?", "Le respect des droits de la défense", ["Le principe de la liberté d'entreprendre", "Le principe de l'autonomie de la volonté", "Le principe de la hiérarchie des normes juridiques", "Le principe de la séparation des pouvoirs"], "Le salarié doit pouvoir s'expliquer avant d'être sanctionné.", 3),
    ("Un employeur sanctionne par une mise à pied sévère un retard de quelques minutes, sans antécédent. Quel principe est en cause ?", "La proportionnalité de la sanction à la faute", ["La liberté syndicale du salarié sanctionné", "Le principe du contradictoire devant le juge de première instance", "L'obligation de reclassement du salarié", "L'obligation de sécurité de l'employeur"], "La sanction doit être proportionnée à la gravité de la faute.", 3),
    ("L'employeur décide de modifier l'heure de début du travail de son équipe d'une demi-heure, sans changer le reste. De quoi s'agit-il en principe, en droit français ?", "D'un simple changement des conditions de travail", ["D'une modification du contrat exigeant l'accord exprès du salarié", "D'un licenciement déguisé", "D'une sanction disciplinaire", "D'une rupture conventionnelle"], "Un ajustement mineur de l'horaire relève du pouvoir de direction.", 4),
    ("L'employeur réduit significativement la rémunération contractuelle d'un salarié sans son accord. Quelle est la règle de principe en droit français ?", "La rémunération contractuelle ne peut être modifiée sans l'accord du salarié", ["L'employeur peut toujours la réduire librement", "Seul le syndicat peut l'accepter à la place du salarié", "Elle peut être modifiée si l'inspecteur le demande", "Elle peut être modifiée si l'entreprise est ancienne"], "La rémunération est un élément essentiel du contrat, qui ne peut être changé unilatéralement.", 4),
    ("Un salarié refuse une modification de son contrat proposée par l'employeur. Que peut faire l'employeur ?", "Renoncer à la modification ou en tirer les conséquences par un licenciement fondé", ["Imposer la modification en toute hypothèse", "Sanctionner le refus comme une faute grave dans tous les cas", "Faire modifier le contrat par l'inspecteur", "Supprimer le contrat de travail sans motif"], "Le refus d'une modification du contrat n'est pas en soi une faute.", 5),
    ("Un employeur mute un salarié dans un autre service du même lieu géographique, pour la même fonction et la même rémunération. Dans la logique habituelle, de quoi s'agit-il ?", "D'un changement des conditions de travail relevant du pouvoir de direction", ["D'une modification du contrat exigeant l'accord", "D'un licenciement économique", "D'une démission du salarié", "D'une sanction obligatoire"], "Sans toucher à un élément essentiel, l'employeur peut décider de façon unilatérale.", 4),
    ("Qu'est-ce qu'une clause de mobilité, de façon générale ?", "Une clause qui permet à l'employeur de changer le lieu de travail dans des limites prévues", ["Une clause qui interdit tout déplacement du salarié", "Une clause qui garantit un salaire maximal", "Une clause qui interdit de travailler pour des concurrents", "Une clause qui réserve le poste à un syndicalisé"], "Elle autorise un changement de lieu, qui doit être mis en œuvre de bonne foi.", 3),
    ("Qu'est-ce qu'une clause de non-concurrence dans un contrat de travail ?", "Une clause qui limite la liberté du salarié d'exercer une activité concurrente après son départ", ["Une clause qui interdit à l'employeur de recruter", "Une clause qui garantit l'exclusivité du salaire", "Une clause qui interdit de se syndiquer", "Une clause qui fixe l'horaire du salarié"], "Elle protège les intérêts légitimes de l'entreprise après la rupture.", 3),
    ("En droit français, quelle condition est exigée pour la validité d'une clause de non-concurrence post-contractuelle ?", "Elle doit être limitée dans le temps et l'espace et être indispensable à l'entreprise", ["Elle doit viser tous les emplois sans limite", "Elle doit être imposée sans aucune contrepartie", "Elle doit être valable pour toute la vie du salarié", "Elle doit être décidée par le syndicat"], "La clause ne doit pas empêcher le salarié de retrouver un emploi ; une contrepartie financière est exigée.", 5),
    ("Un employeur surveille en secret par caméra cachée les salariés, sans les en informer. Quel principe général est méconnu ?", "La loyauté et la transparence dans le contrôle des salariés", ["La liberté d'entreprendre du salarié", "Le droit de grève des salariés", "La liberté syndicale", "Le droit à un salaire minimal"], "Un dispositif de contrôle doit être porté à la connaissance des salariés.", 4),
    ("Un employeur consulte les messages strictement privés d'un salarié sur son téléphone personnel, sans son accord. Quel principe est atteint ?", "La vie privée du salarié", ["Le droit de grève du salarié", "La liberté de réunion syndicale", "Le droit à la formation du salarié", "Le principe d'égalité de rémunération"], "Le salarié conserve sa vie privée au temps et au lieu de travail.", 3),
    ("Un employeur interdit à ses salariés de porter des signes religieux discrets, sans justification liée à la tâche ni règle générale. En principe, que peut-on dire ?", "Les restrictions aux libertés doivent être justifiées par la nature de la tâche et proportionnées", ["L'employeur peut tout interdire sans justification", "Le salarié perd ses libertés en signant le contrat", "Seul un syndicat peut décider des restrictions", "Les libertés n'existent pas dans l'entreprise"], "Les limites aux libertés individuelles doivent être justifiées et proportionnées.", 5),
    ("Un salarié perçoit une prime depuis plusieurs années, de manière constante, générale et fixe. L'employeur décide de la supprimer d'un coup. Quel concept est susceptible de s'appliquer ?", "L'usage d'entreprise", ["Le lock-out", "La grève perlée", "La clause de mobilité", "La prise d'acte"], "Un usage constant, général et fixe crée des droits que l'employeur doit dénoncer régulièrement.", 5),
    ("Un employeur annonce de sa seule volonté une prime à tout le personnel à la fin de l'année. De quoi relève cet acte ?", "D'un engagement unilatéral de l'employeur", ["D'une convention collective de branche négociée avec les syndicats", "D'une sentence arbitrale", "D'un accord d'entreprise négocié", "D'un usage imposé par la loi"], "Une promesse unilatérale précise peut créer des droits pour les salariés.", 5),
    ("Un salarié estime qu'on lui impose une tâche étrangère à sa qualification, sans accord. Quelle est la règle de principe ?", "Un changement de qualification est une modification substantielle du contrat", ["L'employeur peut changer librement la qualification", "Le salarié doit se taire car il est subordonné", "Seul l'inspecteur peut modifier la qualification", "Il n'y a jamais de qualification contractuelle"], "La qualification professionnelle est un élément essentiel du contrat.", 4),
    ("Un salarié reçoit un ordre manifestement illégal de son supérieur, par exemple falsifier des documents officiels. Quel principe général protège sa position ?", "L'obéissance ne couvre pas les ordres manifestement illicites", ["Il doit toujours obéir aux ordres sans exception", "Il commet une faute s'il refuse l'ordre illicite", "L'employeur peut ordonner n'importe quoi", "Le contrat de travail supprime toute responsabilité pénale du salarié"], "La subordination n'impose pas de commettre une infraction.", 4),
    ("Un employeur fait pratiquer des fouilles individuelles de sacs de façon arbitraire sur certains salariés seulement. Quelle exigence est en cause ?", "Les atteintes aux libertés doivent être justifiées, proportionnées et non discriminatoires", ["La nécessité d'obtenir l'accord du juge pour toute surveillance", "L'interdiction de toute règle intérieure", "Le droit de l'employeur de faire ce qu'il veut", "L'obligation pour les salariés de se syndiquer"], "Un contrôle doit reposer sur des règles connues et être non arbitraire.", 4),
    ("Qu'implique le devoir de loyauté du salarié, de façon générale ?", "Qu'il ne nuise pas aux intérêts de l'entreprise pendant l'exécution du contrat", ["Qu'il renonce à tout syndicat pendant le contrat", "Qu'il accepte toute modification de son salaire", "Qu'il ne demande jamais de congés", "Qu'il informe l'employeur de sa vie privée"], "La loyauté interdit notamment de concurrencer son employeur pendant le contrat.", 3),
    ("Un salarié exerce en cachette une activité concurrente de celle de son employeur pendant son contrat. Quelle obligation méconnaît-il ?", "Son obligation de loyauté envers l'employeur", ["Son obligation de sécurité à l'égard de l'employeur", "Son obligation de reclassement", "Son obligation de reprendre le travail après la grève", "Son obligation de verser des cotisations syndicales"], "La concurrence déloyale pendant le contrat est un manquement à l'obligation de loyauté.", 3),
    ("Un employeur refuse de fournir du travail au salarié, tout en continuant à le payer. Que peut-on dire, de façon générale ?", "L'employeur doit en principe fournir le travail convenu", ["L'employeur n'a jamais à fournir de travail", "Le salarié doit fournir lui-même le travail à l'employeur à sa place", "Seul le syndicat peut fournir du travail", "Le juge fournit le travail au salarié"], "Fournir du travail est une obligation essentielle de l'employeur, à côté du paiement du salaire.", 3),
    ("Un employeur retarde chaque mois de plusieurs semaines le paiement du salaire. Quelle obligation fondamentale n'est pas respectée ?", "Le paiement régulier de la rémunération", ["L'obligation de loyauté du salarié", "L'obligation de reclassement", "Le devoir de non-concurrence", "L'obligation d'affiliation syndicale de l'employeur"], "Le salaire est la principale obligation de l'employeur.", 2),
    ("Un employeur impose à un salarié d'exécuter des tâches dangereuses sans aucun équipement de protection. Quel pouvoir dépasse-t-il ?", "Son pouvoir de direction, borné par l'obligation de sécurité", ["Son pouvoir de négociation collective, borné par le syndicat de l'entreprise", "Son pouvoir de représentation, borné par le juge", "Son pouvoir législatif, borné par la constitution", "Son pouvoir de nomination, borné par l'État"], "Le pouvoir de direction s'exerce dans le respect de la santé et de la sécurité.", 3),
    ("Un employeur accorde un meilleur salaire à des hommes qu'à des femmes, à poste et compétences équivalents. Quel principe est violé ?", "L'égalité de rémunération à travail égal", ["Le principe de liberté syndicale", "Le principe de la hiérarchie des normes", "Le principe de la clause de mobilité", "Le principe du préavis"], "À travail de valeur égale, la rémunération doit être égale, sans discrimination.", 3),
    ("Un employeur ne promeut jamais un salarié parce qu'il est syndicaliste, malgré ses qualités. Comment qualifier ce comportement ?", "Une discrimination syndicale", ["Un exercice ordinaire du pouvoir disciplinaire", "Une clause de mobilité", "Un usage d'entreprise", "Un lock-out"], "Prendre en compte l'appartenance syndicale pour décider est interdit.", 3),
    ("Un employeur adopte seul un règlement intérieur qui contient une clause contraire à la loi. Quelle est la valeur de cette clause ?", "Elle est sans effet, le règlement ne pouvant pas déroger aux règles supérieures", ["Elle est valable car l'employeur est maître chez lui", "Elle est valable si elle est affichée", "Elle est valable après un an d'application", "Elle prime sur la loi car elle est plus récente"], "Le règlement intérieur respecte la hiérarchie des normes.", 4),
    ("À qui le règlement intérieur s'impose-t-il, en principe ?", "À tous les salariés de l'entreprise", ["À l'employeur seul, et pas aux salariés", "Aux syndicats uniquement, et pas aux salariés", "Aux seuls salariés signataires d'un écrit spécial", "Aux salariés après approbation du ministre"], "Il fixe des règles générales applicables à toute l'entreprise.", 2),
    ("Peut-on, par le règlement intérieur, prévoir une sanction qui n'est prévue par aucune règle supérieure, par exemple l'amende sur salaire ?", "En principe non, les sanctions pécuniaires sont interdites en droit français", ["Oui, sans aucune limite", "Oui si l'inspecteur est absent", "Oui si le salarié est cadre", "Oui si le délégué du personnel est d'accord"], "Les amendes et sanctions pécuniaires sont prohibées par le droit français du travail.", 5),
    ("Un employeur privilégie une pratique générale favorable aux salariés, durablement appliquée, puis la supprime sans prévenir personne. Qu'aurait-il dû faire ?", "Dénoncer l'usage régulièrement, avec information préalable des intéressés", ["Rien, car il peut la supprimer à tout moment", "Attendre la prochaine grève", "Saisir le tribunal de l'ordre judiciaire pénal", "Obtenir l'autorisation de l'inspecteur du travail"], "Un usage ne peut être supprimé qu'à l'issue d'une dénonciation régulière.", 5),
    ("Quelle est la différence entre pouvoir de direction et pouvoir disciplinaire ?", "Le premier organise le travail, le second sanctionne les fautes", ["Le premier sanctionne les fautes, le second organise le travail", "Le premier appartient aux salariés, le second à l'État", "Le premier concerne les cadres, le second les ouvriers", "Il n'y a aucune différence"], "Organisation du travail d'un côté, sanction des manquements de l'autre.", 2),
    ("Un employeur sanctionne un salarié pour un fait fautif connu depuis très longtemps, sans enquête ni urgence. Quelle règle de principe est méconnue ?", "Le caractère tardif de la sanction", ["La liberté syndicale", "La clause de mobilité", "Le principe de reclassement", "Le principe de non-concurrence entre salariés"], "Les faits fautifs doivent être sanctionnés dans un délai raisonnable ; sinon l'employeur est réputé les avoir tolérés.", 5),
    ("En cas de faute, l'employeur écarte immédiatement le salarié de l'entreprise le temps de décider. Comment appelle-t-on cette mesure ?", "Une mise à pied conservatoire", ["Un lock-out", "Un préavis", "Une clause de mobilité géographique", "Une prise d'acte"], "Elle est provisoire et précède la décision définitive.", 3),
    ("Quelle est la nature de l'avertissement adressé par l'employeur à un salarié fautif ?", "Une sanction disciplinaire légère", ["Un licenciement", "Une démission déguisée", "Une grève décidée par l'employeur", "Un congé forcé"], "L'avertissement est la sanction la plus légère, sans effet sur la présence du salarié.", 2),
    ("Un employeur impose de façon permanente un travail de nuit à un salarié engagé de jour, sans son accord. Quelle analyse est la plus probable en droit français ?", "Un changement important du contrat qui requiert son accord", ["Un changement des conditions de travail ordinaire, par nature", "Une sanction licite sans condition", "Un simple droit de l'employeur sans effet", "Une rupture amiable acquise"], "Passer de jour à nuit bouleverse l'économie du contrat.", 5),
    ("Quelle obligation pèse sur l'employeur à propos de l'égalité de traitement entre salariés placés dans la même situation ?", "Il doit justifier toute différence par des raisons objectives et pertinentes", ["Il peut traiter chacun à sa convenance", "Il doit accorder rigoureusement le même salaire à tous, quelle que soit la fonction", "Il doit consulter chaque salarié avant toute décision", "Il doit éviter de payer les cadres plus que les ouvriers"], "Une différence de traitement doit reposer sur des éléments objectifs et vérifiables.", 5),
    ("Un employeur adopte un code de conduite pour ses salariés mais ne l'affiche nulle part et ne le communique pas. Que peut-on soulever ?", "Son inopposabilité faute d'avoir été porté à la connaissance des salariés", ["Sa validité absolue dès la signature", "Sa nullité automatique de l'entreprise", "Son remplacement par la loi du pays voisin", "Sa transformation en convention collective"], "Un règlement doit être porté à la connaissance de ceux auxquels on l'oppose.", 4),
    ("Un employeur impose la mutation d'un salarié protégé dans un autre établissement sans son accord. Quel principe particulier s'applique en droit français ?", "Le changement des conditions de travail d'un salarié protégé exige son accord", ["Le salarié protégé est traité comme tout autre salarié", "Le salarié protégé est muté d'office par l'inspecteur", "Le salarié protégé est exclu de l'entreprise", "Le salarié protégé n'a aucun droit particulier"], "Les mandats sont protégés : on ne peut leur imposer une modification sans accord.", 5),
    ("Un employeur subordonne l'embauche à la réponse du candidat à des questions sans lien avec le poste (vie intime, opinions). Que peut-on dire ?", "Les questions doivent avoir un lien direct avec l'emploi et l'aptitude professionnelle", ["Toutes les questions sont permises en entretien", "Le candidat doit répondre sous peine de sanction pénale", "L'employeur peut les consigner dans un fichier public", "Le candidat n'a aucun droit en entretien"], "Le recrutement ne peut utiliser que des informations liées à l'aptitude professionnelle.", 3),
    ("Peut-on soutenir qu'un employeur dépasse ses pouvoirs en imposant au salarié de lui remettre les clés de sa vie privée (identifiants de comptes personnels) ?", "Oui, car la vie privée limite le pouvoir de direction", ["Non, le contrat donne tout pouvoir à l'employeur sur la vie du salarié", "Non, car il paie un salaire", "Oui, car le syndicat l'interdit toujours", "Non, car le salarié est subordonné en tout"], "La subordination est limitée à l'exécution du travail.", 4),
    ("Un employeur muni de preuves limitées licencie un salarié en l'accusant de vol, sans enquête sérieuse. Quelle question juridique se pose ?", "Celle du caractère réel et sérieux du motif", ["Celle de la liberté d'entreprendre de l'employeur", "Celle de la compétence du ministre de l'intérieur", "Celle de la validité de la clause de mobilité", "Celle de l'existence d'une convention collective"], "Le motif doit être réel (existant) et sérieux (suffisamment grave) en droit français.", 4),
    ("Qui supporte, de façon générale, la charge du risque économique de l'entreprise dans une relation de travail salariée ?", "L'employeur, non le salarié", ["Le salarié, qui perd son salaire en cas de pertes", "Le syndicat de l'entreprise", "L'inspecteur du travail", "Le juge des affaires du travail"], "Le salarié est payé même si l'entreprise n'est pas bénéficiaire ; le risque est à la charge de l'employeur.", 3),
    ("Quelle est la conséquence juridique d'un changement de lieu de travail imposé qui reste dans le même secteur géographique, sans clause de mobilité ?", "Il peut relever du pouvoir de direction de l'employeur", ["Il est nécessairement nul", "Il équivaut toujours à un licenciement déguisé du salarié", "Il est réservé au juge du travail", "Il exige toujours l'accord du syndicat"], "Dans le même secteur, le changement est en principe un simple changement des conditions de travail.", 5),
    ("Un employeur reproche à un salarié des propos tenus dans un cadre privé, sans lien avec son travail ni préjudice à l'entreprise. Quelle est la règle de principe ?", "Un fait de la vie privée n'est pas en principe une cause de sanction", ["Tout fait de la vie privée peut être sanctionné librement par l'employeur", "L'employeur peut toujours licencier pour la vie privée", "Le salarié ne peut pas avoir de vie privée", "Le contrat de travail couvre toute la vie du salarié"], "La vie personnelle ne peut fonder une sanction que si elle cause un trouble caractérisé à l'entreprise.", 4),
    ("L'employeur est lié par un accord d'entreprise plus favorable aux salariés que sa décision. Que doit-il faire ?", "Appliquer l'accord d'entreprise, plus favorable", ["Appliquer sa décision, qui est plus récente", "Appliquer ce que décide le syndicat", "Attendre dans tous les cas la décision d'un juge avant d'appliquer l'accord", "Ignorer l'accord"], "Une décision unilatérale ne peut remettre en cause un accord plus favorable.", 4),
], size=15)
# ---------------------------------------------------------------- 3. Rupture du contrat de travail
M("rup", [
    ("Mme Abena écrit à son employeur : « Je quitte l'entreprise à compter de ce jour. » De quoi s'agit-il ?", "D'une démission, si la volonté de partir est claire et non équivoque", ["D'un licenciement prononcé par la salariée", "D'un licenciement économique", "D'une rupture conventionnelle imposée", "D'une mise à la retraite d'office"], "La démission est la rupture à l'initiative du salarié, qui exige une volonté claire.", 2),
    ("Un salarié, excédé après une dispute, lance « je démissionne ! » sur le coup de la colère et revient le lendemain. Que retient en principe le juge ?", "Une démission exige une volonté sérieuse et non équivoque, difficile à déduire d'un emportement", ["Une démission valable et irrévocable", "Une rupture conventionnelle", "Un licenciement pour faute grave", "Une prise d'acte automatique"], "Les propos tenus sous le coup de la colère ne traduisent pas toujours une volonté claire.", 4),
    ("Un employeur décide seul de mettre fin au contrat d'un salarié en l'informant par lettre motivée. Quelle est cette rupture ?", "Un licenciement", ["Une démission", "Une prise d'acte", "Une rupture d'un commun accord", "Une retraite volontaire"], "Le licenciement est la rupture décidée par l'employeur.", 1),
    ("Un employeur et un salarié signent un accord mettant fin au contrat à une date convenue, après discussions libres. De quoi s'agit-il ?", "D'une rupture d'un commun accord", ["D'un licenciement pour faute du salarié", "D'une démission forcée", "D'un licenciement économique", "D'une grève prolongée"], "La volonté concordante des deux parties met fin au contrat.", 2),
    ("Un salarié reproche à son employeur le non-paiement de plusieurs mois de salaire et quitte l'entreprise en lui imputant la rupture. De quoi s'agit-il ?", "D'une prise d'acte de la rupture", ["D'une démission ordinaire sans reproche", "D'un licenciement économique", "D'une retraite", "D'un lock-out"], "La prise d'acte est la rupture par le salarié en raison de manquements de l'employeur.", 4),
    ("Après une prise d'acte, le juge estime que les manquements reprochés à l'employeur étaient suffisamment graves. En droit français, quel effet a la prise d'acte ?", "Elle produit les effets d'un licenciement injustifié", ["Elle produit les effets d'une démission", "Elle est sans effet", "Elle produit les effets d'une retraite", "Elle produit les effets d'un détachement dans une autre entreprise"], "Si les faits sont justifiés, la rupture est imputée à l'employeur.", 5),
    ("Un salarié a pris acte de la rupture mais le juge considère que les reproches invoqués ne sont pas fondés. Quelle est la conséquence habituelle ?", "La rupture produit les effets d'une démission", ["La rupture devient un licenciement abusif", "La rupture est annulée automatiquement", "Le contrat reprend de plein droit", "L'employeur doit payer des dommages-intérêts au salarié dans tous les cas"], "Si les griefs ne justifient pas la rupture, elle s'analyse en démission.", 5),
    ("Un employeur licencie un salarié sans lui indiquer aucun motif et sans lettre. Quel défaut principal reproche-t-on à cette rupture ?", "L'absence de notification du motif", ["L'absence de grève", "L'absence d'une clause de mobilité dans le contrat", "L'absence d'accord du syndicat", "L'absence d'inspecteur"], "Le salarié doit connaître les motifs du licenciement pour pouvoir les contester.", 3),
    ("En droit français, quelle exigence générale s'applique au motif d'un licenciement individuel ?", "Il doit être réel et sérieux", ["Il doit être choisi par le salarié", "Il peut être totalement arbitraire", "Il doit être approuvé par le syndicat", "Il doit être économique obligatoirement"], "Le droit français exige une cause réelle et sérieuse.", 3),
    ("Un employeur licencie un salarié en raison d'une grossesse. Que peut-on en dire ?", "Le licenciement est discriminatoire et, en principe, nul", ["Le licenciement est valable si l'entreprise est petite", "Le licenciement est valable avec préavis", "Le licenciement n'est que irrégulier en la forme", "Le licenciement est un simple licenciement disciplinaire"], "Une rupture fondée sur un motif discriminatoire est atteinte de nullité.", 4),
    ("Un salarié se plaint de harcèlement auprès de l'inspection ; l'employeur le licencie en représailles. Que peut-on dire ?", "Le licenciement est une mesure de représailles, en principe nul", ["Le licenciement est valable car l'employeur dirige", "Le licenciement est valable car la plainte du salarié est publique", "Le licenciement n'est qu'un simple avertissement", "Le licenciement est un licenciement économique"], "Sanctionner un salarié qui dénonce des faits protégés est prohibé.", 5),
    ("Un salarié absent plusieurs jours sans aucune explication est licencié pour abandon de poste. Quelle règle de principe protège néanmoins le salarié ?", "L'employeur doit respecter la procédure de licenciement", ["L'employeur peut ignorer toute procédure", "L'abandon de poste est une démission automatique et immédiate", "L'abandon de poste est un droit du salarié", "Le salarié perd tout droit sur-le-champ"], "Même fautif, le salarié bénéficie de la procédure de licenciement.", 4),
    ("Quel est le rôle du préavis lors de la rupture d'un contrat à durée indéterminée ?", "Laisser à l'autre partie un temps pour s'organiser avant la fin du contrat", ["Imposer des sanctions au salarié partant", "Remplacer l'indemnité de licenciement", "Valider rétroactivement la rupture", "Créer un nouveau contrat de travail"], "Le préavis permet au salarié de chercher un emploi et à l'employeur de le remplacer.", 2),
    ("Un salarié est licencié pour faute grave. Que devient, en principe, son droit au préavis ?", "Il le perd, la faute rendant impossible le maintien du contrat", ["Il le conserve toujours en totalité", "Il est doublé par rapport à la règle générale applicable aux autres cas", "Il est transformé en congé payé", "Il est maintenu pour le seul syndicat"], "La faute grave interdit la poursuite du contrat même pendant le préavis.", 4),
    ("Quelle faute justifie classiquement un licenciement sans préavis : celle qui rend impossible le maintien du salarié même temporairement ?", "La faute grave", ["La faute légère", "L'insuffisance de résultats", "L'absence de qualification", "Le retard unique et isolé"], "La faute grave rend impossible la poursuite du contrat pendant le préavis.", 3),
    ("Un employeur reproche à un salarié des résultats insuffisants, sans qu'il y ait mauvaise volonté de sa part. De quoi s'agit-il ?", "D'une insuffisance professionnelle, qui n'est pas une faute en soi", ["D'une faute lourde nécessairement", "D'une faute grave nécessairement", "D'un licenciement économique", "D'un abandon de poste"], "L'insuffisance relève de l'aptitude, non d'une volonté fautive.", 4),
    ("Une entreprise supprime des postes parce que son activité diminue fortement. Quelle sorte de licenciement est en cause ?", "Un licenciement pour motif économique", ["Un licenciement disciplinaire pour faute grave", "Une démission collective", "Une rupture conventionnelle", "Une prise d'acte collective"], "La cause est étrangère à la personne du salarié : difficultés ou réorganisation.", 3),
    ("Avant de licencier pour motif économique, que doit tenter l'employeur, en droit français ?", "Reclasser le salarié sur un autre emploi disponible", ["Obtenir la démission du salarié", "Faire voter les autres salariés", "Réduire immédiatement à zéro le salaire du salarié concerné", "Supprimer le syndicat"], "Le licenciement économique est un dernier recours après recherche de reclassement.", 4),
    ("Un employeur prétend licencier pour motif économique, puis recrute dès le lendemain une personne pour le même poste. Que peut soupçonner le juge ?", "L'absence de réelle cause économique", ["La validité parfaite du licenciement", "Une démission du salarié licencié", "Un accord collectif tacite", "Une grève des salariés"], "Le motif économique doit être réel ; le remplacement immédiat le contredit.", 5),
    ("Un salarié est licencié pour avoir participé à une grève licite. Quelle est en principe la solution en droit français ?", "Le licenciement est nul, sauf faute lourde du gréviste", ["Le licenciement est valable car la grève est une faute", "Le licenciement est valable après préavis", "Le licenciement est une simple irrégularité", "Le licenciement est un licenciement économique"], "La grève licite ne peut justifier un licenciement ; seule la faute lourde le permet.", 4),
    ("Un salarié est licencié pour une faute commise avec la volonté de nuire à son employeur, par exemple le sabotage intentionnel d'une machine. Quelle qualification retient-on ?", "La faute lourde", ["La faute légère", "L'insuffisance professionnelle", "La faute grave sans intention", "Le motif économique"], "L'intention de nuire distingue la faute lourde.", 3),
    ("Un salarié a oublié par négligence de fermer un local, sans intention de nuire, ce qui a causé un dommage important. Quelle qualification est la plus plausible ?", "Une faute simple ou grave, mais pas une faute lourde", ["Une faute lourde obligatoirement, car le dommage est important", "Un motif économique", "Une prise d'acte", "Une démission déguisée"], "Sans intention de nuire, la faute lourde est écartée.", 5),
    ("À quoi sert le certificat de travail remis au salarié à la fin du contrat ?", "À attester les dates d'emploi et les fonctions exercées", ["À établir la culpabilité du salarié devant le juge pénal", "À remplacer le solde de tout compte", "À prouver la faute de l'employeur", "À créer un syndicat"], "Il permet au salarié de justifier de son expérience auprès d'un futur employeur.", 2),
    ("Un employeur refuse de remettre au salarié son certificat de travail. Quel droit du salarié est méconnu ?", "Le droit d'obtenir ce document", ["Le droit de grève", "Le droit de bénéficier d'une clause de mobilité", "Le droit à l'avertissement", "Le droit au lock-out"], "La remise du certificat est une obligation de l'employeur.", 2),
    ("Que récapitule le solde de tout compte ?", "Les sommes versées au salarié lors de la rupture du contrat", ["Les fautes reprochées au salarié", "Les cotisations syndicales du salarié", "Les actions détenues par le salarié", "Les congés pris par l'employeur"], "Il détaille salaire, indemnités et autres sommes dues à la fin du contrat.", 3),
    ("Un contrat à durée déterminée arrive à son terme ; les parties n'ont rien prévu. Que se passe-t-il, en principe ?", "Le contrat prend fin à l'échéance du terme", ["Le contrat se transforme en société", "Le contrat est automatiquement nul", "Le contrat devient un mandat", "L'employeur doit indemniser l'inspecteur du travail du terme atteint"], "L'arrivée du terme met fin au CDD.", 2),
    ("Un employeur met fin à un CDD avant son terme sans faute grave du salarié ni accord. Quelle est la règle de principe en droit français ?", "La rupture anticipée est en principe interdite et ouvre droit à réparation", ["La rupture anticipée est toujours libre", "La rupture anticipée est libre sans indemnité", "La rupture anticipée est réservée à l'inspecteur", "La rupture anticipée est nulle de plein droit pour toute l'entreprise concernée"], "Le CDD n'est rompu avant terme que dans des cas limités : accord, faute grave, force majeure.", 4),
    ("Un incendie détruit entièrement l'entreprise, rendant impossible la poursuite de l'activité, de façon imprévisible et irrésistible. Quel concept peut justifier la fin du contrat ?", "La force majeure", ["La prise d'acte", "Le lock-out", "La faute lourde", "La clause de mobilité"], "Un événement imprévisible, irrésistible et extérieur rend impossible l'exécution du contrat.", 4),
    ("Un employeur signe une transaction avec le salarié après son licenciement, chacun faisant des concessions pour éviter un procès. À quoi sert une transaction ?", "À mettre fin à un litige par des concessions réciproques", ["À annuler le contrat de travail rétroactivement depuis son origine", "À remplacer le certificat de travail", "À fixer la grève", "À créer une convention collective"], "La transaction éteint le litige par concessions mutuelles.", 4),
    ("En droit français, peut-on valablement transiger sur le licenciement avant qu'il soit notifié, en renonçant à le contester ?", "Non, la transaction suppose que la rupture soit définitive et notifiée", ["Oui, à n'importe quel moment", "Oui, mais seulement avant la signature du contrat", "Oui, par simple déclaration orale", "Oui, uniquement avec l'inspecteur"], "On ne transige qu'après la rupture, sur ses conséquences.", 5),
    ("Un salarié atteint l'âge de la retraite et son employeur lui demande de partir contre son gré. Comment parle-t-on, en droit français, de la rupture proposée par l'employeur dans ce cas ?", "D'une mise à la retraite", ["D'un départ volontaire à la retraite du salarié", "D'une démission du salarié", "D'une prise d'acte", "D'une faute lourde"], "Le départ décidé par l'employeur est une mise à la retraite, le départ choisi par le salarié est un départ volontaire.", 5),
    ("Le salarié décide librement de quitter l'entreprise pour prendre sa retraite. Qu'est-ce que cela constitue ?", "Un départ volontaire à la retraite", ["Une mise à la retraite", "Un licenciement économique collectif", "Un licenciement nul", "Un lock-out"], "L'initiative vient du salarié, non de l'employeur.", 3),
    ("Le contrat de travail d'un salarié est transféré à un nouvel employeur à la suite de la vente de l'entreprise. Quel principe général protège les salariés ?", "La poursuite des contrats avec le nouvel employeur", ["La rupture automatique des contrats au moment de la vente", "La transformation des contrats en CDD", "Le versement du prix de vente aux salariés", "La suspension des contrats pendant un an"], "En cas de transfert d'entreprise, les contrats en cours subsistent.", 4),
    ("Un salarié absent pour maladie est licencié uniquement à cause de sa maladie. Quelle logique générale s'applique ?", "Un licenciement fondé sur la santé est discriminatoire", ["Le licenciement pour maladie est toujours régulier", "Le licenciement pour maladie est toujours un licenciement économique", "Le licenciement pour maladie est une démission", "Le licenciement pour maladie suspend le contrat"], "Le droit protège le salarié malade contre une rupture fondée sur son état de santé.", 4),
    ("Un salarié déclaré inapte à son poste à la suite d'un accident du travail ne peut pas être reclassé. Que peut en principe faire l'employeur, en droit français ?", "Engager une procédure de licenciement pour inaptitude, après recherche de reclassement", ["Le licencier sans aucune formalité", "Le maintenir sans travail sans salaire", "Lui imposer une démission", "Supprimer tous ses droits"], "L'inaptitude, une fois le reclassement impossible, peut fonder un licenciement.", 5),
    ("Un employeur adresse au salarié une lettre qui mentionne seulement « motif : insuffisant ». Que peut-on reprocher à cette lettre ?", "Un motif trop vague", ["Un excès de précision sur les faits", "L'absence de signature du syndicat", "L'absence de clause de mobilité", "L'absence de grève"], "Le motif doit être précis pour permettre au salarié de se défendre et au juge de contrôler.", 4),
    ("Que doit faire en principe l'employeur avant un licenciement, en droit français, une fois qu'il envisage la mesure ?", "Convoquer le salarié à un entretien préalable", ["Faire voter le personnel", "Obtenir l'accord du juge", "Demander l'avis préalable du ministre en charge du travail", "Informer la presse"], "L'entretien préalable permet au salarié d'être entendu avant la décision.", 3),
    ("Dans la procédure de licenciement en droit français, quel est l'ordre logique des étapes ?", "Convocation à l'entretien, entretien, puis notification motivée", ["Notification motivée, puis entretien, puis convocation du salarié", "Entretien, notification, puis convocation", "Notification, puis recours au syndicat, puis entretien", "Convocation, notification, puis entretien"], "On entend le salarié avant de décider, puis on notifie la décision.", 4),
    ("En droit français, dans quelle situation la rupture d'un CDD à l'initiative du salarié est-elle, en principe, permise avant le terme ?", "En cas de faute grave de l'employeur, ou d'accord des parties", ["Chaque fois que le salarié trouve un emploi mieux rémunéré ailleurs", "Chaque fois que le salarié le souhaite sans motif", "Seulement avec l'accord du syndicat", "Seulement pendant la grève"], "Le CDD est rompu avant terme dans des cas limités, notamment la faute grave et l'accord.", 5),
    ("Le décès du salarié a quel effet sur le contrat de travail ?", "Il met fin au contrat, qui est conclu en considération de la personne", ["Il transmet le contrat aux héritiers du salarié", "Il suspend le contrat jusqu'à la prochaine grève", "Il transforme le contrat en CDD", "Il oblige l'employeur à reprendre la famille"], "Le contrat de travail est conclu en considération de la personne du salarié, il n'est pas transmissible.", 5),
    ("Un salarié licencié sans respect des formalités mais pour un motif réel et sérieux peut obtenir quoi, en droit français ?", "Une indemnité pour irrégularité de procédure", ["La nullité de l'entreprise", "La réintégration automatique dans tous les cas", "Le transfert du contrat à son syndicat", "La suppression du motif"], "L'irrégularité de forme est sanctionnée sans que le licenciement perde sa cause.", 5),
    ("Quel effet a, en principe, la nullité d'un licenciement ?", "Elle efface la rupture et peut ouvrir droit à la réintégration", ["Elle n'a aucun effet pratique", "Elle transforme le salarié en associé", "Elle rend le salarié débiteur de l'employeur pour les années travaillées", "Elle supprime le droit du travail"], "Le licenciement nul est réputé n'avoir jamais existé.", 4),
    ("Un employeur proclame un « plan social » pour supprimer plusieurs emplois. De quel type de licenciement s'agit-il ?", "D'un licenciement économique collectif", ["D'un licenciement disciplinaire individuel", "D'une démission collective", "D'une grève de l'employeur", "D'une prise d'acte"], "La suppression de plusieurs emplois pour cause économique est un licenciement collectif.", 3),
    ("Un employeur licencie un représentant du personnel élu en passant outre la procédure spéciale de protection. Quelle est la conséquence, en droit français ?", "Le licenciement est irrégulier et le salarié peut demander sa réintégration", ["Le licenciement est valable comme pour les autres", "Le représentant perd son mandat sans recours", "Le licenciement est un licenciement économique", "Le licenciement est une simple démission"], "La protection des représentants exige une autorisation administrative préalable.", 5),
    ("Un salarié licencié est-il tenu d'effectuer son préavis dans tous les cas ?", "Non, notamment en cas de faute grave ou si l'employeur l'en dispense", ["Oui, toujours sans exception", "Non, car le préavis n'existe jamais", "Oui, même en cas de faute lourde", "Non, seulement s'il est syndiqué"], "Le préavis est exécuté sauf dispense ou faute grave.", 4),
    ("Un employeur dispense le salarié d'exécuter son préavis tout en le payant. Que devient la rémunération pendant cette période ?", "Elle est due, comme si le préavis avait été exécuté", ["Elle est supprimée dès la dispense", "Elle est réduite de moitié par principe, quelle que soit la situation", "Elle est versée au syndicat", "Elle est remplacée par un avertissement"], "La dispense décidée par l'employeur ne prive pas le salarié de la rémunération du préavis.", 4),
    ("Un employeur décide de rompre un contrat à durée indéterminée avec un salarié qui a commis une erreur très mineure, sans antécédent. Quelle analyse du motif est probable ?", "Le motif risque de ne pas être jugé suffisamment sérieux", ["Le motif est toujours suffisant", "Le motif est toujours discriminatoire par nature, quel que soit le contexte", "Le motif est un motif économique", "Le motif est une force majeure"], "Le juge apprécie le sérieux du motif au regard de la gravité des faits.", 4),
    ("Un salarié conteste son licenciement. Qui doit apprécier, en dernier ressort, la réalité et le sérieux du motif ?", "Le juge, au vu des éléments fournis par les parties", ["L'employeur seul", "Le syndicat de l'entreprise", "Le ministre du travail", "Le salarié seul"], "Le juge forme sa conviction à partir des éléments produits, le doute profitant au salarié en droit français.", 3),
    ("En droit français, à qui profite le doute lorsqu'il subsiste après examen du juge sur le motif du licenciement ?", "Au salarié", ["À l'employeur", "Au syndicat", "À l'inspecteur du travail", "À l'État"], "Le doute profite au salarié dans le contentieux du licenciement.", 5),
    ("Une salariée est licenciée pendant la période où la loi la protège en raison de sa maternité, sans motif étranger à son état. Quelle est la logique protectrice ?", "Une protection renforcée contre la rupture pendant cette période", ["Aucune protection particulière n'existe", "Une protection réservée aux employeurs", "Une protection limitée aux cadres", "Une protection seulement pour les hommes"], "Le droit protège la salariée enceinte et en congé de maternité contre la rupture.", 4),
    ("Un employeur désire rompre un contrat en échange d'une somme négociée, sans contrainte pour le salarié. De quel mécanisme relève cet accord, en droit français ?", "De la rupture conventionnelle", ["De la démission forcée", "Du lock-out", "De la faute lourde", "De la clause de mobilité du contrat"], "La rupture conventionnelle est un accord libre de rupture, avec des garanties.", 4),
    ("Une salariée a signé sa rupture conventionnelle sous la menace de son employeur. Quel vice du consentement peut être invoqué ?", "La violence", ["La lésion", "L'erreur sur la substance", "Le dol de l'inspecteur", "La contrainte du syndicat"], "Un consentement obtenu par la menace est vicié par violence.", 4),
    ("Un salarié licencié découvre que l'employeur a invoqué de faux motifs pour masquer une volonté de se débarrasser de lui à cause de ses opinions. Quel critère retient le juge ?", "Le véritable motif, non celui qui est affiché", ["Le motif affiché dans la lettre, même s'il est faux", "Le motif le plus récent", "Le motif choisi par le salarié", "Le motif suggéré par le syndicat"], "Le juge recherche la cause réelle de la rupture.", 5),
    ("Un employeur licencie un salarié en raison de ses opinions politiques exprimées hors du travail, sans trouble à l'entreprise. Quelle conclusion générale ?", "Le licenciement est fondé sur un motif discriminatoire et donc illicite", ["Le licenciement est un motif légitime", "Le licenciement est un motif économique", "Le licenciement est une démission", "Le licenciement est une force majeure"], "Les opinions sont une liberté fondamentale protégée.", 4),
], size=15)
# ---------------------------------------------------------------- 4. Représentation du personnel, syndicats, négociation collective
M("rep", [
    ("Les salariés d'une entreprise élisent l'un des leurs pour porter leurs réclamations à l'employeur. De quel représentant s'agit-il ?", "D'un délégué du personnel", ["D'un délégué syndical désigné par un syndicat", "D'un inspecteur du travail nommé par l'État", "D'un arbitre choisi par le tribunal", "D'un administrateur nommé par les actionnaires"], "Le délégué du personnel est élu par le personnel.", 2),
    ("Un syndicat désigne lui-même un salarié pour le représenter dans l'entreprise auprès de l'employeur. De qui s'agit-il ?", "D'un délégué syndical", ["D'un délégué du personnel élu", "D'un inspecteur du travail", "D'un juge du travail", "D'un directeur des ressources humaines"], "Le délégué syndical est désigné par son syndicat, non élu par l'ensemble du personnel.", 3),
    ("Quel est le rôle principal d'un syndicat professionnel, de façon générale ?", "Défendre les intérêts professionnels collectifs", ["Diriger l'entreprise à la place de l'employeur et du conseil", "Rendre la justice entre salariés et employeur", "Fixer le salaire minimum de l'État", "Vérifier la comptabilité de l'entreprise"], "Le syndicat défend les intérêts collectifs de la profession.", 2),
    ("Un employeur refuse d'embaucher une personne parce qu'elle appartient à un syndicat. Quel principe est violé ?", "La liberté syndicale", ["La liberté de la concurrence", "Le droit de l'employeur à la clause de mobilité", "La liberté du commerce et de l'industrie", "Le droit de propriété"], "Nul ne peut être discriminé en raison de son appartenance syndicale.", 2),
    ("Un employeur exige de ses salariés qu'ils quittent leur syndicat sous peine de sanction. Quel principe est atteint ?", "La liberté de s'affilier à un syndicat et de le rester", ["La liberté de ne pas se syndiquer", "La liberté d'entreprendre de l'employeur de façon générale", "Le droit à la clause de non-concurrence", "Le principe de l'égalité devant l'impôt"], "L'employeur ne peut ni imposer ni interdire l'adhésion à un syndicat.", 3),
    ("Un salarié refuse d'adhérer à un syndicat, et un collègue le menace de licenciement. Quelle liberté est en cause ?", "La liberté de ne pas adhérer à un syndicat", ["La liberté de grève", "La liberté d'entreprendre", "La liberté de la concurrence entre entreprises", "La liberté de la presse"], "La liberté syndicale comprend aussi la liberté de ne pas se syndiquer.", 3),
    ("Un employeur gêne volontairement le fonctionnement du comité des représentants du personnel en refusant toute réunion. Quel manquement commet-il ?", "Un délit d'entrave à l'exercice des fonctions de représentation", ["Un abus de la clause de mobilité", "Une faute disciplinaire du salarié", "Un licenciement économique", "Un usage d'entreprise"], "Empêcher les institutions représentatives de fonctionner constitue une entrave.", 4),
    ("Une convention collective est négociée entre syndicats et organisations d'employeurs d'un secteur. Quelle est sa nature ?", "Un accord collectif pour une branche", ["Un contrat individuel unique entre un salarié et son employeur", "Une décision unilatérale de l'employeur", "Une loi votée par le parlement", "Une sentence du tribunal du travail"], "Elle complète la loi pour un secteur donné.", 2),
    ("Une convention collective de branche prévoit une prime ; le contrat individuel d'un salarié n'en parle pas. Que doit appliquer l'employeur, en principe ?", "La prime de la convention, qui s'impose au contrat", ["Rien, car le contrat est silencieux", "La prime seulement si l'inspecteur du travail l'ordonne", "La prime seulement pour les syndiqués", "La prime seulement après une grève"], "La convention collective applicable s'impose aux contrats individuels.", 3),
    ("Un contrat de travail contient une clause moins favorable que la convention collective applicable. Quelle règle s'applique, selon le principe de faveur ?", "La disposition la plus favorable au salarié", ["La disposition la moins favorable au salarié", "La disposition la plus ancienne", "La disposition choisie par l'employeur", "La disposition la plus courte"], "En cas de concours de normes, la plus favorable au salarié l'emporte.", 4),
    ("Une loi d'ordre public impose une règle protectrice ; un accord collectif prévoit une règle moins protectrice. Que décide le principe de hiérarchie des normes ?", "La règle de la loi d'ordre public prime sur l'accord moins protecteur", ["L'accord prime toujours sur la loi", "L'accord prime car il est plus récent", "La règle est choisie par l'employeur", "La loi est écartée car trop générale"], "Un accord ne peut déroger à une règle d'ordre public absolu.", 5),
    ("Quel est l'objet du droit de négociation collective ?", "Permettre aux représentants des salariés et aux employeurs de fixer ensemble des règles du travail", ["Permettre au juge de fixer les salaires", "Permettre à l'État de fermer l'entreprise", "Permettre à l'employeur de dissoudre les syndicats", "Permettre d'organiser une grève"], "La négociation collective crée des normes d'origine professionnelle.", 2),
    ("Un accord est conclu dans une seule entreprise entre l'employeur et les syndicats qui y sont représentés. Comment le qualifie-t-on ?", "Un accord d'entreprise", ["Une convention collective de branche", "Un traité international du travail", "Une loi sociale", "Un règlement administratif"], "L'accord d'entreprise ne vaut que pour l'entreprise concernée.", 3),
    ("Une organisation internationale adopte un texte sur le travail forcé que les États peuvent ratifier. De quel type d'instrument s'agit-il ?", "D'une convention internationale du travail", ["D'une convention collective de branche étendue", "D'un accord d'entreprise", "D'un règlement intérieur", "D'une sentence arbitrale"], "Les conventions de l'OIT sont des traités ouverts à la ratification.", 3),
    ("Quelle est la nature de l'Organisation internationale du travail ?", "Une institution tripartite réunissant États, employeurs et travailleurs", ["Une juridiction internationale de grève", "Un syndicat mondial unique", "Une entreprise multinationale", "Une organisation d'États seuls"], "Les représentants des gouvernements, employeurs et travailleurs y siègent ensemble.", 3),
    ("Un syndicat peut-il agir en justice pour défendre l'intérêt collectif de la profession qu'il représente ?", "Oui, en principe, le syndicat a qualité pour défendre l'intérêt collectif", ["Non, un syndicat n'a jamais accès au juge", "Oui, mais seulement contre l'État", "Non, seul l'employeur peut agir", "Oui, mais seulement à la place d'un juge"], "Les syndicats ont la personnalité juridique et peuvent agir pour l'intérêt collectif.", 3),
    ("Le délégué du personnel est menacé de licenciement à cause de ses réclamations. Quelle protection générale existe pour les représentants ?", "Une protection spéciale contre le licenciement, avec contrôle préalable", ["Aucune protection, le mandat est libre", "Une protection réservée aux employeurs", "Une protection limitée à un seul jour", "Une protection supprimée en cas d'ancienneté"], "Les représentants sont protégés pour pouvoir exercer leur mandat sans crainte.", 4),
    ("Une entreprise doit-elle, en principe, laisser les représentants du personnel exercer leurs fonctions sur le temps de travail ?", "Oui, ils disposent de moyens, dont du temps, pour exercer leur mission", ["Non, ils doivent exercer leur mission en dehors de tout horaire de travail", "Oui, mais sans aucun moyen matériel", "Non, ils renoncent à leur salaire pendant la mission", "Oui, mais seulement le dimanche"], "Des heures de délégation sont prévues, en principe payées comme temps de travail.", 4),
    ("Un syndicat est dit « représentatif ». Que cela signifie-t-il, de façon générale ?", "Qu'il peut négocier au nom des salariés", ["Qu'il remplace l'employeur dans l'entreprise après un vote", "Qu'il est une administration de l'État", "Qu'il est un tribunal du travail", "Qu'il est réservé aux cadres"], "La représentativité confère le droit de négocier et de conclure des accords.", 4),
    ("Un employeur négocie un accord avec une personne qui n'a aucune qualité pour représenter les salariés. Que peut-on soulever ?", "L'invalidité de l'accord faute de partenaire qualifié", ["La validité absolue de l'accord", "La transformation automatique de l'accord en loi votée", "Le caractère obligatoire pour l'État", "La nullité de l'entreprise"], "L'accord collectif doit être conclu avec des représentants habilités.", 4),
    ("Que fait, de façon générale, un comité d'entreprise ou une instance équivalente ?", "Il informe et consulte le personnel sur la marche de l'entreprise", ["Il remplace le juge du travail", "Il fixe seul les salaires", "Il dirige l'entreprise", "Il nomme l'inspecteur du travail"], "Ces instances permettent aux salariés d'être informés et consultés sur les décisions importantes.", 3),
    ("Parmi ces personnes, laquelle n'est pas un représentant du personnel ?", "L'inspecteur du travail", ["Le délégué du personnel", "Le délégué syndical", "Le représentant au comité d'entreprise", "Le membre élu d'un comité de santé et sécurité"], "L'inspecteur du travail est un agent de l'État, non un représentant des salariés.", 2),
    ("Un employeur consulte formellement le comité avant un projet de restructuration, mais ne tient aucun compte de son avis. Qu'est-ce qu'une consultation ?", "Une demande d'avis, qui n'oblige pas l'employeur à le suivre", ["Une obligation de suivre toujours l'avis de l'organe consulté", "Une décision du juge du travail", "Un accord négocié obligatoire", "Une grève préalable"], "Consulter ne signifie pas obtenir un accord, mais l'employeur doit respecter la procédure.", 4),
    ("Un syndicat est créé librement par des travailleurs de la même profession. Quelle condition est habituelle en droit français ?", "Le dépôt des statuts selon la loi", ["Une autorisation préalable du chef de l'entreprise concernée", "Une autorisation du ministre de l'intérieur seul", "L'accord de l'employeur pour exister", "L'inscription au registre du commerce"], "La liberté syndicale suppose une création libre, avec formalités de publicité simples.", 5),
    ("Un employeur accorde des avantages à un syndicat pour qu'il se montre complaisant. Comment qualifie-t-on le risque ?", "Une ingérence de l'employeur dans le fonctionnement syndical", ["Une grève perlée", "Un lock-out", "Une mise à pied conservatoire", "Une prise d'acte"], "L'employeur ne doit pas influencer ou financer un syndicat pour le contrôler.", 5),
    ("Parmi ces éléments, lequel relève du droit collectif du travail ?", "Une convention collective de branche", ["Un contrat d'apprentissage", "Une lettre de licenciement individuelle", "Un avertissement individuel", "Un certificat de travail"], "Le droit collectif traite des rapports entre groupes et organisations.", 2),
    ("Parmi ces éléments, lequel relève du droit individuel du travail ?", "Le contrat de travail d'un salarié", ["La grève", "La convention collective", "L'élection des délégués du personnel", "La négociation de branche"], "Le droit individuel porte sur la relation entre un employeur et un salarié.", 2),
    ("Une convention collective peut être « étendue » par l'autorité publique. Que signifie cela, de façon générale ?", "Qu'elle s'applique à tout le secteur concerné", ["Qu'elle est réservée aux seuls syndiqués", "Qu'elle devient une loi pénale", "Qu'elle est supprimée dans le secteur", "Qu'elle s'applique aux seules entreprises publiques du secteur"], "L'extension étend le champ d'application à tout un secteur d'activité.", 5),
    ("Un salarié n'est pas membre du syndicat signataire de la convention collective applicable à son entreprise. Peut-il en bénéficier ?", "Oui, la convention s'applique à tous les salariés de l'entreprise concernée", ["Non, seuls les syndiqués en bénéficient", "Oui, mais seulement s'il paie une cotisation spéciale", "Non, il doit conclure une convention à part", "Oui, mais seulement pour un an"], "En principe, la convention s'applique à tous les salariés de l'entreprise liée par elle.", 4),
    ("En droit français, qui est lié par une convention collective de branche non étendue ?", "Les employeurs signataires ou membres d'une organisation signataire", ["Chaque employeur du pays, même non signataire", "Seulement les salariés non syndiqués", "Seulement l'inspecteur du travail", "Seulement l'État"], "En l'absence d'extension, l'application dépend de l'adhésion à l'organisation signataire.", 5),
    ("Peut-on mentionner dans un contrat individuel que le salarié renonce par avance à la protection de la convention collective qui lui est plus favorable ?", "Non, on ne peut renoncer à l'avance à des droits protecteurs d'ordre public social", ["Oui, car le contrat prime la convention", "Oui, si l'employeur propose une prime", "Oui, si le salarié est cadre", "Oui, après six mois"], "Les droits tirés de la convention ne peuvent être abandonnés par avance par contrat moins favorable.", 5),
    ("Comment appelle-t-on le principe selon lequel les travailleurs participent, par leurs délégués, à la détermination collective des conditions de travail ?", "Le principe de participation", ["Le principe de faveur", "Le principe de non-concurrence", "Le principe de reclassement"], "Le principe de participation permet aux travailleurs d'intervenir par leurs délégués.", 4),
    ("Un employeur refuse d'afficher les communications syndicales prévues par les règles de l'entreprise. Que peut-on lui reprocher ?", "Une atteinte aux moyens d'action des syndicats", ["Un abus de son pouvoir disciplinaire", "Une rupture abusive du contrat", "Un manquement à la clause de non-concurrence du contrat", "Un défaut de préavis"], "Les syndicats disposent de moyens de communication dans l'entreprise.", 4),
    ("L'élection des délégués du personnel repose sur quel principe général ?", "Le vote des salariés de l'entreprise", ["La nomination directe par l'employeur seul", "La désignation par le juge", "La désignation par l'État", "Le tirage au sort entre salariés"], "L'employeur organise le scrutin, mais ce sont les salariés qui votent.", 3),
], size=15)


# ---------------------------------------------------------------- 5. Grève
M("grv", [
    ("Les ouvriers d'un atelier cessent ensemble le travail pour obtenir une hausse de salaire. Comment qualifier ce mouvement ?", "Une grève", ["Un lock-out", "Une démission collective", "Un abandon de poste ordinaire", "Une prise d'acte individuelle"], "La grève est la cessation collective et concertée du travail pour des revendications professionnelles.", 1),
    ("Un seul salarié cesse de travailler de sa propre initiative pour protester contre une sanction qui ne touche que lui, sans appui collectif. Est-ce une grève au sens classique ?", "Non, la grève suppose en principe une action collective ou concertée", ["Oui, une grève est toujours individuelle", "Oui, car il cesse de travailler", "Non, car la grève est réservée aux cadres", "Oui, si la sanction est injuste"], "Une cessation isolée, sans revendication collective, n'est pas en principe une grève.", 4),
    ("Des salariés cessent le travail pour protester contre une loi sans lien avec leurs conditions de travail. Quelle est la position classique ?", "Une grève purement politique n'est en principe pas protégée comme grève professionnelle", ["Toute grève politique est protégée de la même façon", "La grève politique est un délit pénal sans exception", "La grève politique est une démission collective", "La grève politique est un lock-out"], "La grève doit porter sur des revendications professionnelles pour bénéficier de la protection.", 5),
    ("Pendant une grève licite, quel est l'effet sur le contrat de travail des grévistes ?", "Le contrat est suspendu, non rompu", ["Le contrat est rompu automatiquement", "Le contrat est transformé en CDD", "Le contrat est transféré au syndicat", "Le contrat est nul"], "La grève suspend l'exécution du contrat sans le rompre.", 3),
    ("Un salarié gréviste est-il en principe payé pour la période de grève ?", "Non, la suspension du contrat entraîne en principe la suspension du salaire", ["Oui, intégralement comme s'il travaillait", "Oui, avec une prime en plus", "Oui, par l'État", "Oui, par le syndicat uniquement"], "Sans travail effectué, l'employeur n'a pas à payer le salaire correspondant.", 3),
    ("Un employeur licencie un salarié pour sa seule participation à une grève licite. Que peut en dire un juge, en droit français ?", "Il est nul, sauf faute lourde du salarié", ["Le licenciement est toujours valable", "Le licenciement est un licenciement économique de l'entreprise", "Le licenciement est un simple avertissement", "Le licenciement est un abandon de poste"], "Le droit de grève est constitutionnellement protégé.", 4),
    ("Des grévistes empêchent par la force des collègues non grévistes d'entrer dans l'usine. Quelle règle est méconnue ?", "La liberté de travail des non-grévistes", ["La liberté syndicale de l'employeur de l'usine", "Le droit à un salaire de grève", "Le principe de faveur", "La clause de non-concurrence"], "Le droit de grève ne permet pas d'entraver la liberté de travailler de ceux qui ne font pas grève.", 3),
    ("Des grévistes occupent les locaux de l'entreprise en empêchant l'employeur d'y accéder. Quel est le statut de ce comportement, en principe ?", "Il peut constituer une faute ou un trouble illicite, l'occupation excédant l'arrêt du travail", ["Il est toujours un droit pour les grévistes", "Il est obligatoire pour les non-grévistes", "Il est sans conséquence juridique", "Il est un licenciement du syndicat"], "Le droit de grève ne s'étend pas à l'atteinte à la liberté d'accès ou au droit de propriété.", 5),
    ("Des salariés exécutent le travail de façon volontairement très lente, mais restent à leur poste, pour exercer une pression. Quelle expression désigne ce procédé ?", "Une grève perlée ou du zèle", ["Un lock-out de l'employeur", "Un licenciement collectif", "Une prise d'acte collective", "Un préavis de grève classique et obligatoire"], "Ces comportements ne sont pas nécessairement une cessation complète du travail.", 5),
    ("Une grève qui consiste à arrêter le travail par intermittence, désorganisant la production sans l'arrêter complètement, est dite comment ?", "Perlée", ["Totale et nationale", "Conservatoire", "Conventionnelle", "Substitutive"], "La grève perlée perturbe la production par des arrêts partiels répétés.", 5),
    ("L'employeur ferme l'entreprise et interdit l'accès aux salariés pendant un conflit collectif. Quel nom donne-t-on à cette mesure ?", "Un lock-out", ["Une grève", "Un licenciement", "Un congé payé", "Une mise à pied conservatoire"], "Le lock-out est la fermeture décidée par l'employeur à l'occasion d'un conflit collectif.", 3),
    ("Qui décide de déclencher un lock-out ?", "L'employeur", ["Le syndicat", "Le délégué du personnel", "L'inspecteur du travail", "Le juge du travail"], "À la différence de la grève, qui vient des salariés, le lock-out est une décision patronale.", 2),
    ("Dans les services publics essentiels, la loi impose parfois un préavis de grève ou un service minimum. Pourquoi ?", "Pour concilier le droit de grève avec la continuité du service public", ["Pour supprimer le droit de grève", "Pour permettre à l'employeur de faire grève", "Pour supprimer l'inspecteur du travail", "Pour créer un syndicat unique"], "La continuité du service public est un principe pouvant limiter l'exercice de la grève.", 4),
    ("Dans une entreprise privée, les salariés réclament ensemble le paiement de salaires en retard. Peuvent-ils, en principe, se mettre en grève ?", "Oui, c'est une revendication professionnelle légitime", ["Non, seul l'État peut faire grève", "Non, les salaires ne peuvent jamais être revendiqués collectivement", "Oui, mais seulement si le juge l'autorise d'abord", "Non, les syndiqués seuls peuvent faire grève"], "Le paiement du salaire est un objet de revendication classique.", 2),
    ("Un employeur remplace les grévistes par des travailleurs temporaires embauchés pour la durée de la grève. Quelle est la position générale ?", "Le remplacement de grévistes par des intérimaires est en principe interdit", ["Le remplacement est toujours libre", "Le remplacement est obligatoire", "Le remplacement est réservé aux cadres", "Le remplacement est réservé au syndicat"], "Remplacer les grévistes ruinerait l'effet de la grève ; il est restreint par la loi.", 5),
    ("Un syndicat appelle à la grève ; un salarié non syndiqué souhaite s'y joindre. Peut-il le faire, en principe en droit français ?", "Oui, c'est un droit individuel exercé collectivement", ["Non, seuls les syndiqués peuvent faire grève", "Non, seul le syndicat peut décider pour chacun", "Oui, mais seulement avec l'accord préalable de l'employeur", "Non, il doit démissionner d'abord"], "En droit français, le droit de grève appartient à chaque salarié.", 5),
    ("Un employeur sanctionne des grévistes en fonction de leur participation, par une mise à pied. Quelle règle de principe est méconnue ?", "Nul ne peut être sanctionné pour l'exercice normal du droit de grève", ["L'obligation de préavis du salarié", "La clause de mobilité", "L'obligation de reclassement", "Le devoir de non-concurrence"], "Seule la faute lourde du gréviste peut fonder une sanction.", 4),
    ("Un salarié gréviste commet des violences contre l'encadrement ; l'employeur le sanctionne. La sanction est-elle possible ?", "Oui, car un acte violent peut constituer une faute lourde ou grave individuelle", ["Non, jamais, car la grève protège contre tout", "Non, car seul le syndicat peut sanctionner", "Oui, mais seulement après la fin de la grève nationale", "Non, car la violence est un droit du gréviste"], "Le droit de grève ne couvre pas les fautes personnelles du gréviste.", 4),
    ("Des grévistes installent un piquet devant l'usine pour informer les passants et convaincre leurs collègues. Qu'est-ce qui est licite en principe ?", "L'information et la persuasion pacifiques", ["Le blocage violent de l'accès", "Les menaces aux non-grévistes", "La destruction du matériel", "La séquestration de l'employeur dans son bureau"], "Le piquet est toléré dans les limites du respect de la liberté du travail.", 4),
    ("Un salarié qui suit une grève sans l'avoir annoncée à l'employeur, dans une entreprise privée, est-il en faute pour cette seule raison, en droit français ?", "Non, il n'y a pas, pour le privé, de préavis légal obligatoire de principe", ["Oui, car il faut toujours un préavis de grève", "Oui, car il doit demander l'autorisation du juge", "Oui, car la grève est une démission", "Non, car il doit payer une amende"], "Dans le privé français, les revendications doivent être connues de l'employeur, sans préavis général exigé.", 5),
    ("Pour qu'une grève soit licite, quelle condition essentielle doit être remplie quant à son objet ?", "Elle doit viser des revendications professionnelles", ["Elle doit viser l'abolition d'une loi étrangère quelconque", "Elle doit viser la fermeture de l'entreprise", "Elle doit viser à nuire à un collègue", "Elle doit viser à remplacer l'employeur"], "L'objet professionnel est une condition de licéité.", 3),
    ("Un employeur retient sur le salaire d'un gréviste exactement la part correspondant au temps non travaillé. Que peut-on en dire ?", "La retenue proportionnelle est en principe licite", ["La retenue est toujours illicite", "La retenue doit porter sur la totalité du salaire de toute l'année", "La retenue est une sanction disciplinaire", "La retenue est réservée au syndicat"], "Le salaire est dû en contrepartie du travail, non pendant la cessation du travail.", 4),
    ("Après une grève licite, l'employeur refuse de réintégrer des grévistes à leur poste. Que dire de cette attitude ?", "Elle est abusive, les contrats étant suspendus", ["Elle est normale, les contrats étant rompus par la grève", "Elle est obligatoire", "Elle est un lock-out légitime", "Elle est une rupture d'un commun accord"], "À la fin de la grève, les salariés reprennent leur emploi.", 3),
    ("Un employeur interdit à ses salariés de recourir à toute grève par une clause du contrat. Quelle est la valeur d'une telle clause ?", "Elle est nulle, le droit de grève étant fondamental et protégé", ["Elle est valable si elle est écrite", "Elle est valable si le salarié est cadre", "Elle est valable seulement si le contrat est à durée indéterminée", "Elle est valable après un préavis"], "On ne peut renoncer par avance à un droit fondamental par contrat.", 4),
    ("Qu'est-ce qu'une grève de solidarité ?", "Un arrêt de travail visant à soutenir des collègues d'autres entreprises ou services", ["Un arrêt de travail décidé par l'employeur", "Un arrêt de travail pour maladie collective", "Une fermeture de l'usine par l'État", "Un congé collectif payé"], "La grève de solidarité soutient d'autres travailleurs ; sa licéité dépend de l'intérêt professionnel commun.", 5),
    ("Des travailleurs s'arrêtent de travailler pendant une heure à chaque service pour alerter l'employeur sur leurs conditions de travail. Peut-on parler de grève ?", "Oui, un arrêt de travail collectif, même bref, peut constituer une grève", ["Non, une grève doit durer au moins plusieurs mois", "Non, une grève doit toujours être illimitée", "Oui, mais seulement si l'employeur l'autorise", "Non, c'est un lock-out"], "La durée n'est pas un critère de la grève ; ce qui compte est la cessation collective concertée.", 4),
    ("Un syndicat lance une grève illimitée pour obtenir une augmentation générale ; les négociations échouent. Quelle suite non juridictionnelle classique vise à régler le conflit ?", "Une conciliation ou une médiation", ["Une exécution forcée du contrat", "Un licenciement de l'ensemble du personnel", "Un jugement du tribunal de commerce", "Une saisine du ministre de l'intérieur"], "La conciliation ou la médiation permet de rapprocher les parties.", 3),
    ("Parmi ces mouvements, lequel est un conflit collectif du travail typique ?", "Une grève contre une baisse de salaire d'un service", ["Une demande d'un salarié pour un congé", "Une plainte individuelle d'un salarié pour un retard de paie unique", "Un litige sur une note de frais d'un seul salarié", "Un avertissement adressé à un seul salarié"], "Le conflit collectif oppose un groupe de salariés à l'employeur.", 3),
    ("Qui est, en principe, titulaire du droit de grève en droit français ?", "Le salarié, individuellement, exerçant ce droit collectivement", ["Seulement le syndicat", "Seulement l'employeur", "Seulement l'inspecteur du travail", "Seulement le juge"], "Le droit de grève est un droit individuel dont l'exercice est collectif.", 5),
    ("Un employeur déclare que la grève rompt de plein droit les contrats de tous les grévistes. Cette affirmation est-elle exacte ?", "Non, elle suspend le contrat sans le rompre", ["Oui, la grève rompt toujours le contrat de travail", "Oui, après trois jours de grève", "Oui, pour les cadres uniquement", "Oui, si le syndicat l'accepte"], "La grève suspend l'exécution du contrat.", 3),
    ("Parmi les comportements suivants, lequel pourrait constituer une faute lourde d'un gréviste ?", "Le sabotage intentionnel des machines", ["La simple participation à la grève", "L'information des collègues sur la grève", "La participation à une manifestation pacifique", "La demande d'une augmentation de salaire"], "Seule la faute lourde individuelle, avec intention de nuire, peut justifier un licenciement de gréviste.", 4),
], size=15)


# ---------------------------------------------------------------- 6. Conflits du travail et juridictions
M("conf", [
    ("Un salarié conteste seul son licenciement devant la juridiction du travail. De quel type de conflit s'agit-il ?", "D'un conflit individuel du travail", ["D'un conflit collectif du travail", "D'un conflit de pure politique", "D'un conflit international de souveraineté", "D'un conflit de lois entre États"], "Le litige oppose un salarié à son employeur sur l'application de son contrat.", 1),
    ("Les salariés d'un secteur réclament ensemble une révision de la grille de salaires. De quel type de conflit s'agit-il ?", "D'un conflit collectif du travail", ["D'un conflit individuel du travail", "D'un conflit pénal", "D'un conflit de voisinage", "D'un conflit fiscal"], "Le litige porte sur l'intérêt collectif d'un groupe de salariés.", 1),
    ("Un salarié et son employeur ne s'entendent pas sur l'interprétation d'une clause du contrat. Quelle juridiction est en principe compétente en droit français ?", "La juridiction du travail (conseil de prud'hommes)", ["Le tribunal de commerce", "Le tribunal administratif", "Le tribunal pénal uniquement", "Le conseil constitutionnel"], "Les litiges individuels nés du contrat de travail relèvent de la juridiction du travail.", 3),
    ("En droit français, comment est composé le conseil de prud'hommes ?", "De façon paritaire, de conseillers élus ou désignés côté salariés et côté employeurs", ["Uniquement de magistrats professionnels", "Uniquement de représentants de l'État", "Uniquement de chefs d'entreprise", "Uniquement d'inspecteurs du travail"], "La parité entre représentants des salariés et des employeurs est son trait distinctif.", 3),
    ("Avant d'aller au fond, une juridiction du travail tente en principe de rapprocher les parties. Quelle phase est-ce ?", "La conciliation", ["L'exécution forcée du contrat", "La mise en demeure", "La contrainte par corps", "La prescription"], "La conciliation vise à régler le litige à l'amiable avant le jugement.", 2),
    ("Qu'est-ce qu'une médiation dans un conflit collectif ?", "L'intervention d'un tiers qui propose une solution que les parties restent libres d'accepter", ["L'intervention d'un tiers dont la décision s'impose à tous", "L'intervention du juge pénal", "L'intervention de l'employeur seul", "L'intervention de l'armée"], "Le médiateur propose ; il ne tranche pas.", 3),
    ("Quelle différence existe entre médiation et arbitrage dans un conflit collectif ?", "L'arbitre tranche, le médiateur propose seulement", ["Le médiateur tranche, l'arbitre propose seulement", "Ce sont deux juges permanents de l'État", "Ce sont deux procédures qui imposent la décision de plein droit", "Il n'y a aucune différence"], "La sentence arbitrale s'impose aux parties ayant accepté l'arbitrage.", 4),
    ("Les parties à un conflit collectif conviennent de s'en remettre à la décision d'un tiers choisi par elles. De quelle procédure s'agit-il ?", "Un arbitrage", ["Une grève conservatoire", "Un lock-out", "Une transaction pénale", "Une prise d'acte"], "L'arbitrage repose sur l'accord des parties de se soumettre à une décision.", 3),
    ("Un salarié licencié et son ancien employeur négocient l'indemnité due et signent un accord mettant fin à tout litige. Comment appelle-t-on cet accord ?", "Une transaction", ["Un règlement intérieur", "Un arbitrage", "Un lock-out", "Une convention collective"], "La transaction repose sur des concessions réciproques.", 3),
    ("Que fait l'inspecteur du travail lorsqu'il constate une infraction aux règles de sécurité ?", "Il relève l'infraction et peut mettre l'employeur en demeure de se mettre en conformité", ["Il juge le litige et condamne l'employeur à des dommages-intérêts", "Il licencie le salarié en cause", "Il dirige l'entreprise à la place de l'employeur", "Il négocie à la place du syndicat"], "Il contrôle l'application de la législation du travail, mais ne juge pas.", 3),
    ("L'inspecteur du travail peut-il trancher définitivement un litige individuel de licenciement ?", "Non, cela relève de la juridiction compétente", ["Oui, c'est son rôle principal", "Oui, en tant que juge pénal", "Oui, avec l'accord de l'employeur", "Oui, après avoir consulté le syndicat de l'entreprise"], "L'inspecteur contrôle et concilie, mais ne juge pas les litiges individuels.", 3),
    ("Un salarié et l'employeur sont en désaccord sur un point que leur convention collective prévoit de soumettre à une procédure interne. Que doit faire le salarié avant de saisir le juge ?", "Respecter la procédure de règlement amiable prévue, si elle est obligatoire", ["Ignorer toute procédure interne", "Déclencher une grève immédiate", "Faire fermer l'entreprise", "Démissionner immédiatement"], "Lorsque les parties ont prévu une étape préalable obligatoire, son non-respect peut rendre l'action irrecevable.", 5),
    ("Un salarié affirme avoir été licencié sans motif. Qui doit en principe produire des éléments sur le motif en cas de contestation, en droit français ?", "Chacune des parties, le juge formant sa conviction au vu des éléments", ["Le salarié seul", "L'employeur seul", "Le syndicat seul", "Ni l'une ni l'autre des parties"], "Il n'y a pas de charge exclusive : le juge apprécie les éléments fournis par chacun.", 5),
    ("Quel est le rôle du juge du travail dans un litige individuel ?", "Trancher le litige en appliquant le droit au vu des faits", ["Négocier la convention collective", "Contrôler l'application des règles de sécurité dans les ateliers", "Fixer le salaire minimum national", "Enquêter pour le compte de l'inspecteur"], "Le juge tranche, après avoir entendu les parties.", 2),
    ("Les parties à un contrat de travail ont convenu d'un arbitrage obligatoire pour tout litige futur lié au contrat. Que peut-on dire en droit français ?", "Une telle clause compromissoire est en principe sans effet à l'égard du salarié", ["Elle est valable et obligatoire pour tous", "Elle est valable seulement pour l'employeur", "Elle est une preuve de faute du salarié", "Elle supprime tout droit à agir"], "Le droit français n'admet pas en principe que l'on prive le salarié de son juge naturel.", 5),
    ("Dans un conflit collectif, la sentence arbitrale s'impose-t-elle aux parties qui ont accepté l'arbitrage ?", "Oui, les parties s'étant engagées à respecter la décision de l'arbitre", ["Non, elle n'a aucune force", "Non, elle n'est qu'un avis", "Oui, mais seulement à l'État", "Oui, mais seulement aux non-grévistes"], "Contrairement à la médiation, l'arbitrage aboutit à une décision obligatoire.", 4),
    ("Après un accident, un salarié réclame réparation et l'employeur refuse. À qui le salarié peut-il s'adresser pour trancher ?", "À la juridiction compétente, après les voies amiables éventuelles", ["Au syndicat patronal", "Au banquier de l'entreprise", "À un tirage au sort", "Au maire de la commune"], "Les litiges non résolus à l'amiable sont portés devant le juge.", 2),
    ("Un salarié saisit le juge du travail pour obtenir le paiement d'heures supplémentaires. Que doit-il en principe produire ?", "Des éléments suffisamment précis pour permettre à l'employeur de répondre", ["Aucun élément, le juge devine", "Uniquement la promesse du syndicat", "Seulement un courrier de l'inspecteur", "Un simple témoignage sans lien avec le travail"], "En droit français, la preuve est partagée : le salarié étaye sa demande, l'employeur répond.", 5),
    ("Un salarié estime que l'employeur lui doit des sommes ; il est resté longtemps sans agir. Quelle notion peut jouer contre lui ?", "La prescription, qui éteint le droit d'agir après un délai", ["La clause de mobilité", "La faute lourde", "Le préavis", "Le lock-out"], "Passé un certain délai fixé par la loi, l'action en justice n'est plus recevable.", 4),
    ("Dans un conflit collectif, les parties se réunissent pour discuter des revendications avant tout recours à un tiers. Comment appelle-t-on cette phase ?", "La négociation directe", ["La contrainte", "Le préavis", "L'exécution forcée", "Le jugement"], "Les parties tentent d'abord de trouver elles-mêmes un accord.", 2),
    ("Dans le traitement d'un conflit collectif, quel est l'ordre habituel des étapes de règlement pacifique ?", "Négociation directe, puis conciliation ou médiation, puis éventuellement arbitrage", ["Arbitrage, puis conciliation, puis négociation", "Médiation, puis grève, puis licenciement", "Lock-out, puis négociation, puis arbitrage", "Jugement pénal, puis négociation, puis grève"], "On privilégie les voies de plus en plus contraignantes seulement si les précédentes échouent.", 4),
    ("Un salarié a conclu une transaction après son licenciement. Peut-il ensuite, en principe, réclamer ce à quoi il a renoncé dans la transaction ?", "En principe non, elle éteint le litige réglé", ["Oui, toujours librement", "Oui, à condition d'avoir adhéré à un nouveau syndicat", "Oui, car la transaction est nulle d'office", "Oui, sans limite dans le temps"], "La transaction a autorité de la chose jugée entre les parties dans les limites de son objet.", 5),
    ("Une salariée saisit la juridiction du travail contre une décision qu'elle estime discriminatoire. Que doit-elle présenter en droit français pour que la charge de la preuve se déplace ?", "Des éléments laissant supposer une discrimination", ["La preuve absolue et complète de la discrimination alléguée", "Rien du tout", "Un jugement pénal préalable", "L'aveu de l'employeur"], "L'employeur doit ensuite prouver que sa décision est justifiée par des éléments objectifs.", 5),
    ("En cas de conflit sur l'interprétation d'une convention collective, qui peut interpréter son sens, en principe ?", "Une commission paritaire d'interprétation ou le juge, selon le cas", ["L'employeur seul", "Le salarié seul", "L'inspecteur du travail seul", "Le banquier de l'entreprise"], "Les conventions prévoient souvent une commission d'interprétation ; à défaut, le juge tranche.", 5),
    ("Un salarié de nationalité étrangère est victime d'un litige de travail dans un pays où il travaille légalement. Quelle règle s'applique de façon générale ?", "Il bénéficie en principe de la protection du droit du travail du pays d'exécution du travail", ["Il ne bénéficie d'aucune protection", "Il relève seulement du droit de son pays d'origine dans tous les cas", "Il relève seulement du droit du siège de l'entreprise", "Il relève seulement du droit international pénal"], "Le lieu habituel d'exécution du travail est un critère de rattachement majeur.", 5),
    ("La juridiction du travail peut-elle ordonner la réintégration d'un salarié dont le licenciement est nul ?", "Oui, en principe en droit français, lorsque le salarié le demande", ["Non, jamais", "Oui, mais seulement si l'entreprise y consent toujours expressément", "Non, elle ne peut que prononcer des peines", "Oui, mais seulement le syndicat peut la demander"], "La nullité du licenciement permet la réintégration.", 4),
    ("Un employeur est condamné au paiement de rappels de salaire et refuse d'exécuter la décision devenue définitive. Quelle suite est possible ?", "L'exécution forcée de la décision", ["L'annulation du jugement par l'employeur seul", "La prescription immédiate", "La suppression du droit du salarié", "La médiation obligatoire"], "Une décision définitive peut être exécutée par les voies d'exécution.", 3),
    ("Quelle est la nature d'un différend portant sur l'interprétation d'une règle existante (par exemple le calcul d'une prime) ?", "Un conflit juridique, tranché par le juge", ["Un conflit d'intérêts, tranché par un lock-out", "Un conflit d'intérêts, tranché par la grève obligatoire", "Un conflit pénal, tranché par l'inspecteur", "Un conflit fiscal, tranché par le syndicat"], "Un conflit portant sur l'application d'un droit existant est dit juridique.", 5),
    ("Quelle est la nature d'un différend où des salariés demandent la création d'un avantage nouveau (par exemple une prime inexistante) ?", "Un conflit d'intérêts, en principe négocié", ["Un conflit juridique, résolu par le juge seul à l'audience", "Un conflit pénal", "Un conflit de compétence", "Un conflit fiscal"], "Il s'agit d'obtenir un droit nouveau, non d'appliquer un droit existant.", 5),
    ("Un délégué du personnel porte à l'employeur la réclamation d'un salarié sur le paiement de son salaire. Quelle fonction exerce-t-il ?", "Il porte une réclamation individuelle ou collective auprès de l'employeur", ["Il juge le litige en dernier ressort", "Il remplace l'inspecteur du travail", "Il décide du licenciement", "Il fixe unilatéralement le salaire"], "Le délégué du personnel présente les réclamations ; il n'est pas juge.", 2),
    ("Un salarié saisit l'inspecteur du travail d'une plainte pour non-respect des règles d'hygiène. Quel est le rôle de l'inspecteur ?", "Constater l'infraction et agir pour la faire cesser", ["Rendre un jugement civil", "Licencier l'employeur", "Prendre la direction de l'entreprise pour ensuite licencier", "Négocier une convention de branche"], "L'inspecteur contrôle l'application de la législation.", 2),
    ("Qu'est-ce qui distingue le conflit collectif du conflit individuel quant à son objet ?", "Le conflit collectif porte sur un intérêt collectif, l'individuel sur la situation d'une personne", ["Le conflit collectif ne concerne jamais l'employeur", "Le conflit individuel ne concerne jamais le contrat", "Le conflit collectif est toujours pénal", "Il n'y a aucune différence"], "L'objet du litige détermine sa nature collective ou individuelle.", 3),
    ("Un salarié, après une audience de conciliation, accepte une proposition de l'employeur et signe un procès-verbal de conciliation. Quel est l'effet de cet accord ?", "Il met fin au litige dans les limites de l'accord", ["Il est sans effet juridique", "Il oblige l'employeur seul", "Il transforme automatiquement le litige en conflit collectif", "Il transfère le contrat au syndicat"], "La conciliation réussie règle le différend.", 3),
    ("Un employeur conteste la régularité de la saisine d'une juridiction du travail parce que la procédure obligatoire préalable n'a pas été suivie. Que peut-il soulever ?", "Une fin de non-recevoir", ["Une clause de mobilité géographique", "Un lock-out", "Une prise d'acte", "Une grève perlée"], "Le défaut d'une étape obligatoire peut rendre la demande irrecevable.", 5),
    ("Qui peut assister ou représenter un salarié devant la juridiction du travail, en principe en droit français ?", "Un représentant syndical ou un avocat, selon les règles de procédure", ["Uniquement l'employeur", "Uniquement l'inspecteur du travail", "Uniquement un huissier", "Personne, il doit venir seul"], "La représentation est ouverte, notamment aux défenseurs syndicaux et avocats.", 4),
], size=15)


# ---------------------------------------------------------------- 7. Sécurité, santé et accidents du travail
M("sec", [
    ("Un maçon chute d'un échafaudage non protégé sur un chantier pendant ses heures de travail. Comment qualifier l'événement ?", "Un accident du travail", ["Un accident de la vie privée", "Une maladie professionnelle", "Un accident de trajet", "Un cas de force majeure"], "L'accident survenu par le fait ou à l'occasion du travail est un accident du travail.", 1),
    ("Une salariée se blesse sur le chemin direct entre son domicile et son lieu de travail, à l'heure habituelle. Comment qualifie-t-on généralement l'accident ?", "Un accident de trajet", ["Un accident de loisirs", "Un accident de grève", "Une maladie professionnelle", "Un accident sans aucun lien avec le travail"], "Le trajet aller-retour entre domicile et travail est protégé de façon voisine.", 2),
    ("Un ouvrier développe, après des années d'exposition à une substance dangereuse dans son atelier, une maladie liée à cette exposition. Quelle notion s'applique ?", "Une maladie professionnelle", ["Un accident de trajet", "Un accident soudain du travail", "Une faute lourde du salarié", "Un cas de force majeure"], "La maladie résulte de l'exposition prolongée aux risques du métier.", 2),
    ("Quelle distinction sépare classiquement l'accident du travail de la maladie professionnelle ?", "L'accident est soudain, la maladie progressive", ["L'accident est toujours progressif et la maladie est toujours soudaine", "L'accident concerne les cadres, la maladie les ouvriers", "L'accident est indemnisé, la maladie jamais", "Il n'y a aucune différence"], "La soudaineté de l'événement distingue l'accident ; la durée d'exposition, la maladie.", 3),
    ("Un employeur refuse de fournir des casques et des chaussures de sécurité sur un chantier dangereux. Quelle obligation méconnaît-il ?", "Son obligation de sécurité", ["Son obligation de non-concurrence", "Son obligation de préavis", "Son obligation de reclassement", "Son obligation d'affiliation à un syndicat"], "L'employeur doit prendre les mesures nécessaires pour protéger la santé et la sécurité des salariés.", 2),
    ("Un employeur a prévenu les accidents par des formations, des équipements et une organisation adaptée, mais un accident survient quand même. Que peut-on dire de son obligation de sécurité ?", "Elle porte sur la prévention des risques, appréciée selon les mesures prises", ["Elle est inexistante en cas d'accident", "Elle impose de payer le salarié sans que les mesures de prévention aient une importance", "Elle est supprimée dès la signature du contrat", "Elle ne concerne que les cadres"], "L'employeur doit prouver avoir pris toutes les mesures de prévention nécessaires.", 5),
    ("Quelle est la logique générale du régime de réparation des accidents du travail ?", "Une indemnisation fondée sur le risque professionnel, sans preuve d'une faute de l'employeur", ["Une indemnisation sur preuve d'une faute lourde de la victime", "Une indemnisation réservée aux fautes pénales", "Une absence de réparation", "Une indemnisation par le syndicat"], "Le régime repose sur la théorie du risque professionnel.", 4),
    ("En droit français, qu'appelle-t-on faute inexcusable de l'employeur ?", "Un manquement grave à l'obligation de sécurité malgré la conscience du danger", ["Une faute commise uniquement par le salarié", "Une faute du syndicat de l'entreprise", "Un simple retard de paiement du salaire", "Une démission collective"], "Cette faute peut ouvrir droit à une réparation majorée.", 5),
    ("Un salarié, convaincu d'un danger grave et imminent pour sa vie, quitte son poste sans autorisation. De quel droit peut-il se prévaloir, en droit français ?", "Du droit de retrait", ["Du droit de grève", "Du droit de lock-out", "Du droit de non-concurrence", "Du droit de reclassement"], "Le droit de retrait permet de quitter une situation dangereuse sans sanction.", 3),
    ("Un salarié exerce son droit de retrait de manière légitime, face à un danger sérieux et immédiat. L'employeur peut-il le sanctionner, en principe, en droit français ?", "Non, aucune sanction ne peut être prise en raison d'un retrait légitime", ["Oui, toute absence est une faute", "Oui, par une mise à pied systématique", "Oui, par un licenciement immédiat", "Oui, par une retenue de tout le salaire annuel"], "L'exercice légitime du droit de retrait est protégé.", 4),
    ("Un salarié se retire de son poste en invoquant un risque que rien ne rend dangereux, par pur prétexte. Que peut-on dire ?", "Le retrait injustifié peut être sanctionné", ["Le retrait est toujours justifié", "Le retrait est obligatoire pour tous les salariés", "Le retrait est un droit de grève", "Le retrait est un lock-out"], "Le droit de retrait suppose un motif raisonnable de croire à un danger grave et imminent.", 4),
    ("Quel rôle joue le médecin du travail, de façon générale ?", "Prévenir l'altération de la santé des travailleurs du fait de leur travail", ["Contrôler l'application du Code du travail dans toutes les entreprises du pays", "Rendre la justice du travail", "Nommer les représentants du personnel", "Fixer le salaire des travailleurs"], "Il veille à l'adaptation du travail à l'homme et suit l'état de santé des salariés.", 2),
    ("À l'issue d'un examen, le médecin du travail déclare un salarié inapte à son poste. Qui décide ensuite des suites sur le contrat ?", "L'employeur, après recherche de reclassement, selon les règles applicables", ["Le médecin, qui licencie lui-même", "Le syndicat, qui reclasse le salarié", "L'inspecteur du travail, qui fixe le nouveau poste", "Le salarié seul, sans l'employeur"], "L'avis d'inaptitude oblige l'employeur à rechercher un reclassement avant tout licenciement.", 5),
    ("Qu'est-ce que le document d'évaluation des risques, en droit français ?", "Un document recensant les risques professionnels de l'entreprise", ["Un contrat conclu avec chaque salarié", "Un règlement de la grève", "Une convention de branche", "Un procès-verbal de conciliation"], "L'employeur évalue et consigne les risques pour organiser la prévention.", 4),
    ("Un employeur ne forme pas ses salariés à la manipulation d'une machine dangereuse. Quel volet de la sécurité néglige-t-il ?", "L'obligation de formation à la sécurité", ["L'obligation de reclassement", "L'obligation de non-concurrence", "L'obligation de préavis", "L'obligation de représentation syndicale du personnel"], "La formation à la sécurité fait partie de la prévention.", 3),
    ("Un salarié est victime de moqueries répétées et d'humiliations de la part de son supérieur, ce qui dégrade sa santé. De quoi peut-il s'agir ?", "D'un harcèlement moral", ["D'un conflit collectif", "D'un lock-out", "D'une clause de mobilité", "D'une faute lourde du salarié"], "Des agissements répétés dégradant les conditions de travail caractérisent le harcèlement moral.", 3),
    ("Un supérieur impose des avances insistantes à une subordonnée, malgré ses refus. Quelle qualification vient à l'esprit ?", "Un harcèlement sexuel", ["Un usage d'entreprise", "Un engagement unilatéral", "Un conflit collectif", "Une grève de solidarité"], "Des comportements répétés à connotation sexuelle imposés à la victime sont du harcèlement sexuel.", 3),
    ("L'employeur reçoit le signalement d'un harcèlement moral et ne fait rien. Quelle obligation est méconnue ?", "L'obligation de prendre les mesures nécessaires pour faire cesser et prévenir le harcèlement", ["L'obligation de licencier la victime", "L'obligation de reclasser l'auteur", "L'obligation de suspendre l'entreprise", "L'obligation de négocier une convention"], "L'employeur est responsable de la prévention et du traitement du harcèlement.", 4),
    ("Un salarié harcelé est-il protégé s'il dénonce les faits de bonne foi ?", "Oui, il ne peut être sanctionné pour les avoir relatés", ["Non, la dénonciation est une faute", "Non, il doit se taire pour garder son emploi", "Oui, mais seulement s'il quitte l'entreprise", "Oui, mais seulement si l'auteur des faits est un simple collègue"], "La dénonciation de bonne foi est protégée.", 4),
    ("Une femme enceinte est affectée à un travail dangereux pour sa grossesse. Quel principe protecteur est méconnu ?", "La protection de la maternité, qui impose d'éviter les risques pour la salariée enceinte", ["Le principe de faveur seul", "Le principe de la clause de mobilité", "Le principe de la non-concurrence", "Le principe de l'usage d'entreprise"], "Le droit prévoit une protection renforcée des salariées enceintes.", 3),
    ("Un employeur fait travailler des enfants à des tâches lourdes et dangereuses. Quel principe général du droit du travail est violé ?", "L'interdiction du travail dangereux pour les jeunes, en vertu des normes internationales", ["La liberté syndicale", "Le droit de grève", "La liberté de la concurrence", "Le droit au solde de tout compte"], "Les conventions internationales du travail interdisent les pires formes de travail des enfants.", 3),
    ("Parmi les mesures suivantes, laquelle relève de la prévention des risques professionnels ?", "L'installation de protections sur les machines", ["Le paiement de l'indemnité de licenciement au salarié", "La conclusion d'un CDD", "La remise du certificat de travail", "La négociation d'une convention collective"], "La prévention vise à éviter la survenance des risques.", 2),
    ("Dans une entreprise, quelle instance a pour mission de contribuer à la protection de la santé et à l'amélioration des conditions de travail ?", "Une commission ou un comité d'hygiène et de sécurité", ["Le tribunal de commerce", "Le syndicat patronal", "Le comité des actionnaires", "Le conseil des ministres"], "Ces instances associent le personnel à la prévention.", 3),
    ("Un salarié se blesse en effectuant, sur ordre de son employeur, une course personnelle de ce dernier. Pourquoi retient-on probablement un accident du travail ?", "Parce qu'il agissait sous l'autorité de l'employeur pour son compte", ["Parce qu'il était en congé", "Parce qu'il agissait pour son propre loisir", "Parce qu'il était gréviste", "Parce qu'il était syndiqué"], "L'accident survenu à l'occasion du travail sous l'autorité de l'employeur est un accident du travail.", 3),
    ("Un salarié se blesse en pratiquant un loisir sportif pendant ses congés, sans lien avec l'entreprise. Qualifie-t-on cet accident d'accident du travail ?", "Non, il n'y a aucun lien avec le travail", ["Oui, tout accident d'un salarié est un accident du travail", "Oui, car il est salarié", "Oui, car il a un contrat en cours", "Oui, car il touche un salaire"], "Il manque le lien avec le travail.", 2),
    ("Une salariée subit un malaise sur son poste. L'employeur soutient qu'il n'y a pas d'accident du travail faute de preuve d'un événement extérieur. Quelle logique de preuve intervient en droit français ?", "Une présomption d'imputabilité au travail pour l'accident survenu au lieu et temps de travail", ["Aucune présomption n'existe", "Une présomption de faute de la salariée", "Une présomption d'accident de trajet", "Une présomption de grève"], "Dans de nombreux systèmes, l'accident survenu au temps et au lieu de travail est présumé accident du travail.", 5),
    ("Qu'est-ce que la suspension du contrat de travail pour accident du travail implique, de façon générale ?", "Le salarié ne travaille pas, mais son contrat n'est pas rompu et il bénéficie d'une protection", ["Le contrat est rompu de plein droit", "Le salarié perd tout droit au retour à l'emploi", "L'employeur peut le licencier sans motif", "Le contrat devient un CDD"], "La suspension préserve le droit de retrouver son emploi, avec une protection particulière contre le licenciement.", 4),
    ("Un employeur licencie un salarié en arrêt à la suite d'un accident du travail, sans faute grave ni impossibilité de maintenir le contrat. Que peut-on dire en droit français ?", "La protection particulière contre le licenciement pendant la suspension est méconnue", ["Le licenciement est toujours valable pendant l'arrêt", "Le licenciement est obligatoire", "Le licenciement est le choix du médecin", "Le licenciement est un lock-out"], "Pendant la suspension pour accident du travail, le licenciement n'est possible que dans des cas limités.", 5),
    ("En droit français, qui doit déclarer l'accident du travail aux organismes compétents ?", "L'employeur, dans les formes et délais prévus", ["Uniquement le syndicat", "Uniquement le salarié lui-même, sans l'employeur", "Uniquement l'inspecteur du travail", "Personne, la déclaration n'existe pas"], "L'employeur a l'obligation de déclarer l'accident survenu à ses salariés.", 3),
    ("Un salarié respire quotidiennement de la poussière toxique faute de ventilation. Quel manquement de l'employeur est visible ?", "Un manquement à l'obligation de sécurité et de protection de la santé", ["Un manquement à l'obligation de non-concurrence", "Un manquement à l'obligation de mobilité", "Un manquement au préavis", "Un manquement à la clause de dédit-formation"], "La protection de la santé impose de supprimer ou de réduire les risques d'exposition.", 3),
    ("Un salarié est tenu de travailler de façon excessive, sans repos, ce qui met sa santé en danger. Quelle exigence générale est méconnue ?", "Le droit au repos et à la limitation de la durée du travail", ["Le droit de grève", "Le droit de non-concurrence", "Le droit à la prime d'ancienneté", "Le droit syndical"], "Le droit du travail encadre la durée du travail et garantit des repos.", 3),
    ("Un employeur impose le port d'un équipement de protection individuelle ; un salarié refuse sans motif. Que peut-on dire ?", "Le refus de respecter les consignes de sécurité peut constituer une faute", ["Le refus est toujours un droit du salarié", "Le refus est un droit de grève", "Le refus est un droit de retrait", "Le refus est sans conséquence"], "Le salarié doit respecter les consignes de sécurité qui lui sont données.", 3),
    ("Quelle est la règle générale concernant le salarié victime d'un accident causé par sa propre imprudence légère ?", "Il est en principe quand même couvert par le régime de réparation du risque professionnel", ["Il perd toute indemnisation", "Il est licencié automatiquement", "Il doit rembourser son employeur", "Il est considéré comme gréviste"], "Le régime des accidents du travail indemnise en principe sauf faute intentionnelle.", 4),
    ("Un salarié provoque volontairement son propre accident pour percevoir une indemnité. Que peut-on dire ?", "La faute intentionnelle de la victime peut exclure l'indemnisation", ["Il sera toujours indemnisé", "Il sera indemnisé deux fois", "Il devient l'associé de l'employeur", "Il sera titulaire d'un droit de retrait"], "La faute intentionnelle est une cause d'exclusion du régime de réparation.", 5),
    ("En quoi consiste le suivi médical du salarié dans l'entreprise, de façon générale ?", "En des visites médicales pour vérifier l'aptitude et prévenir les risques", ["En une enquête sur ses opinions", "En une sanction disciplinaire", "En un test de recrutement discriminatoire", "En un jugement du tribunal"], "La médecine du travail contribue à la prévention et à l'adaptation du poste.", 3),
    ("Un travailleur de nuit voit sa santé se dégrader en raison du rythme imposé. Quelle exigence générale est en cause ?", "L'adaptation du travail à l'homme et la prise en compte de sa santé", ["Le principe de la clause de mobilité", "Le principe de l'usage d'entreprise", "Le principe de la non-concurrence", "Le principe de la grève perlée"], "La santé du salarié doit guider l'organisation du travail.", 4),
    ("Un salarié dénonce à l'inspecteur du travail des manquements graves de sécurité ; l'employeur le licencie pour ce motif. Que peut-on dire, de façon générale ?", "Le salarié est protégé contre les représailles pour avoir dénoncé de bonne foi des manquements", ["Le licenciement est valable car la dénonciation est déloyale", "Le licenciement est un motif économique", "Le licenciement est une démission", "Le licenciement est une force majeure"], "Les lanceurs d'alerte ou salariés dénonçant des manquements de bonne foi sont protégés.", 5),
    ("Un employeur qui fait travailler un salarié dans un local insalubre manque à quelle obligation essentielle ?", "À celle de fournir un travail sain et sûr", ["À celle de payer l'impôt sur les sociétés de l'entreprise", "À celle de négocier avec l'État", "À celle de reclasser le salarié", "À celle de consulter le juge"], "Les locaux doivent respecter les règles d'hygiène et de sécurité.", 2),
    ("Selon le principe général de prévention, que faut-il privilégier face à un risque ?", "Le supprimer à la source plutôt que protéger chacun", ["Se limiter à fournir des équipements de protection individuels", "Attendre qu'un accident survienne avant d'agir", "Transférer le risque aux seuls salariés exposés", "Réserver la prévention aux grandes entreprises"], "Combattre le risque à sa source est le principe de la prévention.", 5),
    ("Un employeur ignore l'avis d'inaptitude d'un salarié et le maintient à son poste dangereux. Quelle conséquence peut en découler ?", "Un manquement à l'obligation de sécurité engageant sa responsabilité", ["Aucune conséquence", "Une démission du salarié", "Une grève de l'employeur", "Un lock-out"], "L'employeur doit tenir compte des avis du médecin du travail.", 4),
    ("Qui, dans l'entreprise, est responsable en premier lieu de l'organisation de la sécurité ?", "Le chef d'entreprise", ["Le délégué syndical", "Le médecin seul", "L'inspecteur du travail", "L'ouvrier le plus ancien"], "Le chef d'entreprise est tenu d'organiser la prévention.", 2),
    ("Un salarié se blesse en participant, à la demande de l'employeur, à un séminaire organisé hors de l'entreprise. Pourquoi peut-on retenir un accident du travail ?", "Il était sous l'autorité de l'employeur dans l'intérêt de l'entreprise", ["Il était libre de toute obligation", "Il agissait pour son seul plaisir", "Il était en grève", "Il n'était pas encore engagé"], "L'accident survenu à l'occasion de la mission confiée par l'employeur est couvert.", 4),
], size=15)


# ---------------------------------------------------------------- 8. Exécution du contrat : salaire, temps de travail, suspension, discrimination
M("exe", [
    ("Un employeur verse chaque mois un salaire inférieur au minimum garanti par les règles applicables. Que peut réclamer le salarié ?", "Le complément de salaire correspondant, le minimum étant impératif", ["Rien, car il a accepté le contrat", "Seulement une prime facultative", "Seulement un avertissement pour l'employeur", "Le versement du complément à l'inspecteur"], "Un salaire minimum légal ou conventionnel s'impose aux parties.", 3),
    ("Un salarié accepte par écrit un salaire inférieur au minimum légal. Cet accord est-il valable ?", "Non, le minimum est d'ordre public et ne peut être écarté par accord individuel", ["Oui, la signature suffit", "Oui, si le salarié est débutant", "Oui, si l'employeur est en difficulté", "Oui, si le contrat est à durée déterminée"], "On ne déroge pas par contrat aux règles protectrices d'ordre public.", 4),
    ("Un salarié reçoit chaque mois un document détaillant son salaire, ses retenues et les cotisations. De quoi s'agit-il ?", "D'un bulletin de paie", ["D'un certificat de travail", "D'un règlement intérieur", "D'un solde de tout compte", "D'une lettre de licenciement"], "Le bulletin de paie récapitule la rémunération et ses éléments.", 1),
    ("L'employeur règle une partie du salaire par la mise à disposition d'un logement. Comment appelle-t-on cet avantage ?", "Un avantage en nature", ["Une prime de lock-out", "Une indemnité de préavis", "Une cotisation syndicale", "Une indemnité de licenciement"], "Un avantage fourni en nature en contrepartie du travail peut constituer un élément de rémunération.", 2),
    ("Un employeur verse chaque année depuis longtemps une prime de fin d'année identique à tous les salariés, sans l'avoir écrite. Quelle notion peut la faire devenir obligatoire ?", "L'usage d'entreprise", ["La clause de mobilité", "Le lock-out", "Le préavis", "La prise d'acte"], "Constance, généralité et fixité d'une pratique créent un usage.", 4),
    ("Un salarié accomplit des heures au-delà de l'horaire normal à la demande de l'employeur. Quel est le principe général ?", "Ces heures sont en principe rémunérées ou compensées, souvent avec une majoration", ["Ces heures sont toujours gratuites", "Ces heures sont toujours interdites", "Ces heures sont réservées aux syndicats", "Ces heures annulent le contrat"], "Les heures supplémentaires donnent droit à une rémunération majorée ou à un repos compensateur.", 3),
    ("Un salarié effectue des heures supplémentaires de sa seule initiative, sans demande ni accord de l'employeur. Quelle logique s'applique en principe ?", "Elles ne sont dues que si l'employeur les a demandées ou acceptées, au moins tacitement", ["Elles sont toujours dues", "Elles sont toujours interdites au salarié", "Elles sont dues au syndicat", "Elles sont dues à l'inspecteur du travail"], "Il faut que l'employeur ait demandé ou accepté, même implicitement, ces heures.", 5),
    ("Un salarié reste à disposition de l'employeur sans pouvoir vaquer librement à ses occupations, prêt à intervenir. Que retient-on généralement ?", "Il s'agit de temps de travail effectif", ["Il s'agit d'un congé", "Il s'agit d'une grève", "Il s'agit d'une suspension de contrat sans salaire", "Il s'agit de la période d'essai"], "Le temps pendant lequel le salarié est à la disposition de l'employeur sans pouvoir vaquer librement est du travail effectif.", 4),
    ("Un salarié est joignable à son domicile en cas de besoin, libre de s'occuper de ses affaires et ne se rend sur place que s'il est appelé. De quoi s'agit-il ?", "D'une astreinte", ["D'un lock-out", "D'un préavis", "D'une prise d'acte", "D'une grève du zèle"], "L'astreinte est une période où le salarié, sans être à la disposition permanente de l'employeur, doit pouvoir être joint.", 5),
    ("Quelle est la finalité du repos hebdomadaire et des congés annuels, de façon générale ?", "Protéger la santé du salarié et lui permettre de se reposer", ["Réduire les salaires", "Ouvrir la voie au licenciement", "Favoriser le lock-out", "Remplacer le préavis"], "Le droit au repos est un élément de la protection de la santé et de la vie personnelle.", 2),
    ("Un salarié a acquis des droits à congé annuel et la relation prend fin avant qu'il en ait profité. Que lui est-il dû, en principe ?", "Une indemnité compensatrice pour les congés non pris", ["Rien du tout", "Un avertissement", "Une mise à pied", "Une retenue sur salaire"], "Les congés acquis et non pris donnent lieu à une indemnité compensatrice.", 4),
    ("Un salarié tombe malade et bénéficie d'un arrêt de travail régulier. Quel est l'effet sur le contrat ?", "Le contrat est suspendu, non rompu", ["Le contrat est rompu", "Le contrat est transformé en CDD", "Le contrat est transféré à l'assurance", "Le contrat est nul"], "La maladie suspend l'exécution du contrat.", 2),
    ("Un salarié est mis à pied à titre disciplinaire pour une courte période à la suite d'une faute. Quel effet a cette sanction sur le contrat ?", "Une suspension du contrat et du salaire", ["Une rupture définitive", "Une transformation en CDD", "Un transfert définitif à un autre employeur", "Une annulation du contrat"], "La mise à pied disciplinaire est une suspension sans salaire.", 3),
    ("L'entreprise réduit temporairement son activité pour une cause économique conjoncturelle et ne donne plus de travail à certains salariés, sans rompre les contrats. Comment parle-t-on de cette situation ?", "D'un chômage technique", ["D'un lock-out", "D'une démission collective", "D'une prise d'acte", "D'une rupture conventionnelle"], "Le contrat est suspendu et le salarié est parfois indemnisé selon les règles applicables.", 5),
    ("Une salariée est en congé de maternité. Quelle est la situation du contrat ?", "Il est suspendu, avec une protection particulière contre la rupture", ["Il est rompu", "Il devient un CDD", "Il est transféré à l'assurance", "Il est sans effet"], "La suspension préserve l'emploi, avec une protection renforcée.", 3),
    ("À l'issue d'un congé de maternité, une salariée revient dans l'entreprise. Que lui reconnaît-on, en principe ?", "Le droit de retrouver son emploi ou un emploi similaire avec une rémunération équivalente", ["Le droit à un licenciement immédiat", "Le droit de choisir l'employeur", "Le droit de réclamer l'emploi du supérieur", "Le droit d'imposer sa rémunération"], "Le retour dans l'emploi est garanti.", 4),
    ("Une offre d'emploi précise qu'elle s'adresse « uniquement aux hommes » alors que le poste ne l'exige pas. Quelle est la logique du droit du travail ?", "Elle est discriminatoire et prohibée", ["Elle est un droit absolu de l'employeur", "Elle est une obligation légale", "Elle est un usage d'entreprise", "Elle est une clause de mobilité"], "Le sexe ne peut être un critère de recrutement sauf exigence professionnelle essentielle.", 3),
    ("Une règle neutre en apparence (par exemple une exigence de taille) désavantage en fait un groupe protégé sans justification. Comment qualifie-t-on ce cas ?", "Une discrimination indirecte", ["Une discrimination directe, par nature", "Un usage d'entreprise", "Une clause de mobilité", "Un engagement unilatéral"], "La discrimination indirecte résulte d'une règle apparemment neutre qui produit un désavantage particulier.", 5),
    ("Un employeur refuse explicitement de recruter une personne en raison de son origine. Comment qualifie-t-on cette décision ?", "Une discrimination directe", ["Une discrimination indirecte", "Une clause de mobilité", "Un usage d'entreprise", "Un lock-out"], "La différence de traitement est fondée expressément sur un critère prohibé.", 3),
    ("Un salarié en situation de handicap demande des aménagements raisonnables de son poste pour pouvoir travailler. Que lui reconnaît le droit général ?", "Le droit à des aménagements raisonnables, sauf charge disproportionnée pour l'employeur", ["Le droit à n'importe quel aménagement, quel qu'en soit le coût", "Aucun droit particulier", "Le droit d'être licencié sans motif", "Le droit de faire grève sans préavis"], "L'employeur doit prendre des mesures appropriées, dans la limite d'une charge raisonnable.", 5),
    ("Un employeur évince un candidat âgé par principe, sans motif lié au poste. Quel principe est méconnu ?", "L'interdiction de discriminer selon l'âge", ["L'interdiction de toute clause de mobilité", "L'interdiction de la grève", "Le principe du solde de tout compte", "Le principe de non-concurrence"], "L'âge ne peut fonder une décision d'embauche sans justification objective.", 3),
    ("Une entreprise est vendue et le nouvel employeur conteste son obligation de reprendre l'ancienneté acquise. Quelle règle générale est invoquée par les salariés ?", "La continuité des contrats avec maintien des droits acquis en cas de transfert", ["La rupture automatique des contrats à la vente", "Le remplacement par des CDD", "La renonciation obligatoire à l'ancienneté", "La perte du salaire de base"], "Le transfert d'entreprise ne doit pas porter atteinte aux droits acquis des salariés.", 5),
    ("En droit français, un employeur retient sur salaire une somme pour compenser un matériel cassé par un salarié, sans faute lourde. Quelle règle générale protège le salarié ?", "L'employeur ne peut pas faire supporter au salarié le risque de l'entreprise, sauf faute lourde", ["L'employeur peut toujours retenir sur salaire", "Le salarié doit toujours rembourser", "L'employeur est obligé de licencier", "La retenue est une prime"], "La responsabilité pécuniaire du salarié est limitée à la faute lourde.", 5),
    ("Un salarié doit-il garder le secret sur les informations confidentielles de l'entreprise après la fin du contrat ?", "Oui, l'obligation de confidentialité peut survivre à la rupture", ["Non, toute obligation s'éteint à la rupture", "Non, il peut les vendre à un concurrent", "Oui, mais seulement envers un syndicat", "Non, la confidentialité n'existe pas en droit du travail du tout"], "Le secret professionnel ou de fabrication n'est pas levé par le départ.", 4),
    ("Une clause du contrat oblige le salarié à rembourser sa formation s'il démissionne rapidement. Comment appelle-t-on ce type de clause ?", "Une clause de dédit-formation", ["Une clause de non-concurrence", "Une clause de mobilité", "Une clause d'exclusivité", "Une clause de préavis"], "Elle compense l'investissement de l'employeur dans la formation du salarié.", 5),
    ("Un salarié s'engage à travailler exclusivement pour son employeur pendant toute la durée du contrat. Quelle clause cela évoque-t-il ?", "Une clause d'exclusivité", ["Une clause de non-concurrence post-contractuelle", "Une clause de mobilité", "Une clause de dédit-formation", "Une clause de préavis"], "Elle interdit l'exercice d'autres activités pendant l'exécution, sous conditions de proportionnalité.", 4),
    ("Un salarié exerce un travail à l'étranger pour le compte d'une entreprise de son pays d'origine, dans le cadre d'une mission temporaire. Quelle notion évoque cette situation ?", "Le détachement", ["Le lock-out", "La prise d'acte", "Le solde de tout compte", "La grève de solidarité"], "Il y a détachement quand le salarié travaille temporairement hors de son lieu habituel.", 4),
], size=15)


# ---------------------------------------------------------------- 9. Distinctions voisines et intrus
M("dis", [
    ("Quelle différence y a-t-il entre un licenciement et une démission ?", "L'initiative : l'employeur d'un côté, le salarié de l'autre", ["Le licenciement exige toujours un préavis, la démission jamais", "La démission est décidée par l'employeur, le licenciement par le salarié", "Le licenciement concerne les cadres, la démission les ouvriers", "Le licenciement est un contrat, la démission une sanction"], "Le licenciement vient de l'employeur, la démission du salarié.", 1),
    ("Quelle différence y a-t-il entre grève et lock-out ?", "La grève émane des salariés, le lock-out de l'employeur", ["La grève émane de l'employeur, le lock-out des salariés", "La grève est toujours illicite, le lock-out toujours licite", "La grève concerne l'État, le lock-out les syndicats", "La grève dure un jour, le lock-out un an"], "Les deux sont des moyens d'action collective, mais pas du même camp.", 3),
    ("Quelle différence y a-t-il entre conciliation et arbitrage ?", "La conciliation rapproche les parties, l'arbitrage tranche par une décision", ["La conciliation tranche par une décision, l'arbitrage rapproche les parties", "La conciliation est réservée aux syndicats, l'arbitrage aux cadres", "La conciliation est pénale, l'arbitrage est administratif", "La conciliation est toujours gratuite, l'arbitrage toujours payant"], "L'arbitre rend une sentence ; le conciliateur aide à trouver un accord.", 4),
    ("Quelle différence y a-t-il entre faute grave et faute lourde ?", "La faute lourde suppose une intention de nuire", ["La faute grave suppose une intention de nuire que la faute lourde exclut", "La faute lourde est toujours plus légère qu'un simple retard", "La faute grave est réservée aux dirigeants de l'entreprise", "La faute lourde ne concerne que le temps de grève"], "L'intention de nuire est la marque de la faute lourde.", 4),
    ("Quelle différence y a-t-il entre convention collective et accord d'entreprise ?", "Le champ d'application : une branche pour la première, une entreprise pour le second", ["La première est un contrat individuel, le second est collectif", "La première vaut pour une seule entreprise, le second pour toute une branche professionnelle", "La première est une loi, le second un règlement intérieur", "La première est rédigée par l'inspecteur, le second par le juge"], "Le niveau de négociation distingue les deux textes.", 3),
    ("Quelle différence y a-t-il entre modification du contrat et changement des conditions de travail, en droit français ?", "La première exige l'accord du salarié, le second relève du pouvoir de direction", ["La première relève du pouvoir de direction, le second exige l'accord", "La première concerne les cadres, le second les ouvriers", "La première est une sanction, le second une récompense", "Chacune exige l'accord de l'inspecteur du travail"], "Un élément essentiel du contrat ne se modifie pas sans accord.", 4),
    ("Quelle différence y a-t-il entre délégué du personnel et délégué syndical ?", "Le premier est élu par le personnel, le second désigné par son syndicat", ["Le premier est désigné par son syndicat, le second est élu par le personnel", "Le premier représente l'employeur, le second les salariés", "Le premier est un agent de l'État, le second un salarié", "Le premier dirige la grève, le second juge les litiges"], "La source de la légitimité diffère : élection ou désignation.", 3),
    ("Quelle différence y a-t-il entre accident du travail et maladie professionnelle ?", "L'accident est un événement soudain, la maladie vient d'une exposition", ["L'accident vient d'une exposition prolongée, la maladie d'un événement soudain", "L'accident est réservé aux cadres, la maladie aux ouvriers", "L'accident est indemnisé, la maladie ne l'est jamais", "Il n'existe aucune différence juridique entre les deux"], "L'un est brutal, l'autre résulte d'un risque auquel on s'expose dans la durée.", 3),
    ("Quelle différence y a-t-il entre démission et prise d'acte de la rupture ?", "La prise d'acte repose sur des manquements reprochés à l'employeur", ["La démission repose toujours sur des manquements reprochés à l'employeur", "La prise d'acte est décidée par l'employeur seul", "La démission est décidée par le juge du travail", "La prise d'acte exige toujours l'accord du syndicat"], "Dans la prise d'acte, le salarié rompt en imputant la faute à l'employeur.", 5),
    ("Quelle différence y a-t-il entre usage d'entreprise et engagement unilatéral de l'employeur ?", "L'usage naît d'une pratique répétée, l'engagement d'une promesse expresse", ["L'usage naît d'une promesse expresse, l'engagement d'une pratique répétée", "L'usage est écrit, l'engagement toujours oral", "L'usage concerne un salarié, l'engagement tout un secteur", "L'usage est négocié, l'engagement est imposé par le juge"], "Dans les deux cas l'employeur est lié, mais la source diffère.", 5),
    ("Quelle différence y a-t-il entre mise à pied conservatoire et mise à pied disciplinaire ?", "La première est provisoire en attendant une décision, la seconde est une sanction", ["La première est une sanction définitive, la seconde est une mesure provisoire d'attente", "La première est décidée par le juge, la seconde par le syndicat", "La première concerne le temps partiel, la seconde le temps plein", "La première est un congé payé, la seconde un congé sans solde"], "L'une est une mesure d'attente, l'autre une sanction à part entière.", 5),
    ("Quelle différence y a-t-il entre départ volontaire à la retraite et mise à la retraite ?", "Le premier vient du salarié, la seconde de l'employeur", ["Le premier vient de l'employeur, la seconde du salarié", "Le premier est un licenciement, la seconde une démission", "Le premier est réservé aux cadres, la seconde aux ouvriers", "Le premier est décidé par le juge, la seconde par la loi"], "L'initiative est l'élément distinctif.", 4),
    ("Quelle différence y a-t-il entre inspecteur du travail et juge du travail ?", "Le premier contrôle l'application des règles, le second tranche les litiges", ["Le premier tranche les litiges, le second contrôle l'application des règles", "Le premier est élu par le personnel, le second par l'employeur", "Le premier est un syndicaliste, le second un expert comptable", "Le premier siège dans l'entreprise, le second dans le ministère"], "L'un est un agent de contrôle, l'autre une juridiction.", 3),
    ("Quelle différence y a-t-il entre travail dissimulé et travail à temps partiel ?", "Le premier échappe aux obligations déclaratives, le second est une modalité légale", ["Le premier est une modalité légale de travail, le second échappe aux obligations déclaratives", "Le premier concerne le public, le second le privé", "Le premier est un contrat de société, le second un mandat", "Le premier est rémunéré en nature, le second en espèces"], "L'un est illicite, l'autre est un temps de travail réduit parfaitement licite.", 3),
    ("Parmi ces éléments, lequel n'est pas une sanction disciplinaire classique ?", "Le préavis de démission", ["L'avertissement", "La mise à pied disciplinaire", "Le blâme écrit inscrit au dossier", "Le licenciement pour faute"], "Le préavis est une période liée à la rupture, non une sanction.", 3),
    ("Parmi ces éléments, lequel n'est pas un mode de rupture du contrat de travail à durée indéterminée ?", "Le lock-out", ["Le licenciement", "La démission", "La rupture d'un commun accord", "La mise à la retraite"], "Le lock-out est un moyen d'action collective, non un mode de rupture du contrat.", 3),
    ("Parmi ces éléments, lequel n'est pas un moyen d'action collective des salariés ?", "Le lock-out", ["La grève", "La manifestation professionnelle", "Le droit de pétition", "La grève du zèle"], "Le lock-out est un moyen d'action de l'employeur.", 3),
    ("Parmi ces personnes, laquelle n'a pas le pouvoir de sanctionner disciplinairement un salarié ?", "L'inspecteur du travail", ["L'employeur", "Le chef d'entreprise", "Le dirigeant disposant d'une délégation de pouvoir", "Le représentant légal de l'entreprise"], "L'inspecteur contrôle mais n'exerce pas le pouvoir disciplinaire.", 3),
    ("Parmi ces sources, laquelle est la moins élevée dans la hiérarchie des normes du travail ?", "Le contrat individuel de travail", ["La Constitution", "La loi", "Les conventions internationales ratifiées", "La convention collective de branche"], "Le contrat individuel ne peut déroger aux normes supérieures dans un sens moins favorable.", 4),
    ("Parmi ces mesures, laquelle relève du pouvoir de direction plutôt que du pouvoir disciplinaire ?", "L'organisation des équipes de travail", ["L'avertissement écrit", "La mise à pied disciplinaire", "Le blâme", "Le licenciement pour faute lourde"], "Organiser le travail est un acte de direction, non une sanction.", 3),
    ("Parmi ces éléments, lequel est un indice de subordination ?", "Le pouvoir d'adresser des directives et de sanctionner", ["La liberté de fixer ses propres tarifs", "La clientèle personnelle du travailleur", "La liberté de refuser des missions", "L'achat du matériel par le travailleur"], "Directives, contrôle et sanction sont les marques de la subordination.", 2),
    ("Parmi ces organes, lequel n'est pas une instance représentative du personnel ?", "L'inspection du travail", ["Le délégué du personnel", "Le comité d'entreprise", "Le comité d'hygiène et de sécurité", "Le délégué syndical"], "L'inspection du travail est un service de l'État.", 2),
    ("Parmi ces comportements, lequel n'est pas une atteinte à la liberté syndicale ?", "Le refus d'une augmentation générale pour des raisons économiques", ["Le refus d'embaucher un candidat syndiqué", "Le licenciement d'un délégué à cause de son mandat", "L'obligation d'adhérer à un syndicat d'entreprise", "Le fait de payer un syndicat pour obtenir de lui une attitude docile"], "Un refus économique d'augmenter n'est pas lié à la liberté syndicale.", 4),
    ("Parmi ces affirmations sur la grève licite, laquelle est exacte ?", "Elle suspend le contrat de travail", ["Elle rompt le contrat de travail", "Elle supprime le droit à l'emploi pour toujours", "Elle oblige l'employeur à payer pour les jours de grève sans condition", "Elle est interdite dans toute entreprise privée"], "Le contrat est suspendu pendant la grève.", 3),
    ("Parmi ces affirmations sur le règlement intérieur, laquelle est exacte ?", "Il doit respecter la loi et les conventions applicables", ["Il peut écarter la loi si l'employeur le veut", "Il est négocié avec le syndicat, sans l'employeur", "Il est rédigé par l'inspecteur seul", "Il remplace le contrat de travail de chaque salarié"], "Il ne peut contenir de clause contraire aux règles supérieures.", 3),
    ("Parmi ces affirmations sur la période d'essai, laquelle est exacte ?", "Elle permet d'évaluer les compétences du salarié", ["Elle empêche toute rupture dans tous les cas", "Elle supprime le droit du salarié au salaire", "Elle exclut tout recours à la justice", "Elle est un contrat distinct du contrat de travail"], "L'essai sert à tester la collaboration, sans effacer les droits fondamentaux.", 2),
    ("Parmi ces mesures, laquelle relève de la prévention des risques professionnels ?", "La formation des salariés à la sécurité", ["La procédure de licenciement", "L'entretien préalable", "La négociation salariale annuelle dans l'entreprise", "L'élection des délégués"], "Former à la sécurité fait partie de la prévention.", 2),
    ("Parmi ces modes de règlement des conflits collectifs, lequel aboutit à une décision qui s'impose aux parties ?", "L'arbitrage", ["La conciliation", "La médiation", "La négociation directe", "Le préavis"], "L'arbitre rend une sentence obligatoire pour les parties qui l'ont acceptée.", 3),
    ("Quelle expression désigne le plus précisément l'élément qui différencie un contrat de travail d'un contrat d'entreprise ?", "La subordination juridique", ["La rémunération en argent", "La durée de la relation", "La nature manuelle du travail", "Le lieu d'exécution"], "La rémunération se retrouve dans les deux, la subordination non.", 3),
    ("Quelle expression désigne un accord par lequel les deux parties renoncent à une part de leurs prétentions pour éviter un procès ?", "Une transaction", ["Un préavis", "Un règlement intérieur", "Une convention collective", "Un avertissement"], "Les concessions réciproques sont le cœur de la transaction.", 3),
    ("Quelle expression désigne la fermeture de l'entreprise décidée par l'employeur à l'occasion d'un conflit ?", "Un lock-out", ["Un préavis", "Un chômage conjoncturel", "Une clause de dédit", "Une démission collective"], "Le lock-out est la contrepartie patronale de la grève.", 3),
], size=15)


